INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1002-tretij-polufinal-vserossijskogo-konkursa-nastavnikov-byt-a-ne-kazatsya-proshel-v-khabarovske','Третий полуфинал Всероссийского конкурса наставников «Быть, а не казаться!» прошел в Хабаровске','2020-01-01','novosti','[]','Мероприятие объединило более 500 участников из 21 региона Дальневосточного и Сибирского федеральных округов - наставники и педагоги, Герои России, а также молодые патриоты в возрасте от 16 лет. Конкурс проводится по поручению Президента России Владимира Путина . Впервые в качестве эксперта на него был приглашен представитель профсоюзов. Им выступила заместитель председателя Хабаровского Профобъеди','/index.php/news/vse-novosti/1002-tretij-polufinal-vserossijskogo-konkursa-nastavnikov-byt-a-ne-kazatsya-proshel-v-khabarovske','/images/news/77ff0821-3040-45f1-970d-820a8395f1af.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1005-litsa-pobedy-dilshad-yakubovich-azizov','Лица Победы: Дильшад Якубович Азизов','2020-01-01','novosti','[]','Бывший технический инспектор труда Хабаровской краевой организации Общероссийского профсоюза работников автомобильного транспорта и дорожного хозяйства. Дильшад Якубович родился 23 октября 1929 года. Уже в 13 лет пошел трудиться на оборонное предприятие, где выпускались снаряды для фронта. Там он проработал слесарем-инструментальщиком до конца войны. Получив высшее образование, посвятил 45 лет сво','/index.php/news/vse-novosti/1005-litsa-pobedy-dilshad-yakubovich-azizov','/images/news/p4280299.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1006-zavershaetsya-registratsiya-na-ezhegodnyj-vserossijskij-konkurs-eto-u-nas-semejnoe','Завершается регистрация на ежегодный Всероссийский конкурс "Это у нас семейное"','2020-01-01','novosti','[]','Он реализуется в целях создания условий для укрепления института семьи, продвижения в обществе семейных ценностей путем выявления и поддержки семей с активной жизненной позицией. В конкурсе принимают участие семейные команды, состоящие из четырех и более человек, которые являются по отношению друг к другу представителями трех и более поколений. В составе команды должен быть участник от 5 до 17 лет','/index.php/news/vse-novosti/1006-zavershaetsya-registratsiya-na-ezhegodnyj-vserossijskij-konkurs-eto-u-nas-semejnoe',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1009-litsa-pobedy-klavdiya-nikolaevna-krutikova','Лица Победы: Клавдия Николаевна Крутикова','2020-01-01','novosti','[]','Бывший инструктор организационного отдела аппарата Краевого совета профессиональных союзов (нынешнее Хабаровское краевое объединение организаций профсоюзов). Клавдию Николаевну война застала совсем юной 13-летней школьницей. Желая хоть как-то помочь, она пошла работать в колхоз: бралась за любую работу наравне со взрослыми, трудилась на ферме, на покосе и в конюшне. В 1945 году, закончив школу, по','/index.php/news/vse-novosti/1009-litsa-pobedy-klavdiya-nikolaevna-krutikova','/images/news/krutikova1.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1011-litsa-pobedy-anastasiya-pavlovna-skorkina','Лица Победы: Анастасия Павловна Скоркина','2020-01-01','novosti','[]','Своими «секретами долголетия» поделилась бывший главный бухгалтер Территориальной организации Российского профсоюза работников судостроения Хабаровского края , которая 4 января отметит свой 100-летний юбилей. Анастасия Павловна встречает нас на пороге квартиры и сразу видно, как она рада гостям. Её энергия переключается на кухню, где на плите разогревается обед. На тумбочке кипит самовар. В комнат','/index.php/news/vse-novosti/1011-litsa-pobedy-anastasiya-pavlovna-skorkina','/images/news/skorkina1.jpeg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1013-profsoyuzy-v-gody-velikoj-otechestvennoj-vojny','Профсоюзы в годы Великой Отечественной войны','2020-01-01','novosti','[]','(Из книги «Краткая история профсоюзов России с краткой хрестоматией» Александра Шершукова, издание 2024 г., глава «Глава VIII. На войне. 1940-е годы») 22 июня 1941 года нацисты вторглись на советскую территорию и за считанные недели далеко продвинулись вглубь СССР. Уже спустя два дня был создан правительственный Совет по эвакуации, ответственный за перемещение в безопасные регионы страны промышлен','/index.php/news/vse-novosti/1013-profsoyuzy-v-gody-velikoj-otechestvennoj-vojny',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1014-profsoyuzy-ob-yavili-2025-god-godom-trudovoj-doblesti-vsjo-dlya-pobedy','Профсоюзы объявили 2025 год - Годом трудовой доблести «Всё для Победы!»','2025-01-28','novosti','[]','2025 год – 80-летие Великой Победы. Это особенная дата для нашей страны, символизирующая единство народа, его силу духа и стойкость. Мы не только чтим героев, отдавших свои жизни за Родину, но и ещё раз напоминаем всему миру о значимости тех событий. В знак нашей немеркнущей памяти о событиях Великой Отечественной войны, о грандиозной Победе над нацизмом, как символ неразрывной преемственности пок','/index.php/news/vse-novosti/1014-profsoyuzy-ob-yavili-2025-god-godom-trudovoj-doblesti-vsjo-dlya-pobedy',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1016-svoi-znaniya-po-istorii-profsoyuznogo-dvizheniya-proverili-chleny-profsoyuzov-khabarovskogo-kraya','Свои знания по истории профсоюзного движения проверили члены профсоюзов Хабаровского края','2020-01-01','podderzhka','[]','Просветительская акция «Профсоюзный диктант» прошла сегодня в Хабаровском Профобъединении. Участие в ней приняли более 30 представителей отраслевых профсоюзов края и аппарата ХКООП. Акция была организована Академией труда и социальных отношений в рамках Года трудовой доблести «Всё для Победы!», объявленного Федерацией независимых профсоюзов России. Участникам предстояло ответить на 10 тестовых зад','/index.php/news/vse-novosti/1016-svoi-znaniya-po-istorii-profsoyuznogo-dvizheniya-proverili-chleny-profsoyuzov-khabarovskogo-kraya','/images/news/img_8468.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1017-konvert-v-chest-120-letiya-rossijskikh-profsoyuzov-postupil-v-pochtovoe-obrashchenie','Конверт в честь 120-летия российских профсоюзов поступил в почтовое обращение','2020-01-01','novosti','[]','В минувшую пятницу мы отметили две знаменательные даты: 35 лет со дня образования ФНПР и 120 лет со дня оформления легального профсоюзного движения в России. По этому случаю АО «Марка» выпустила художественный маркированный конверт, тираж которого составил 500 тысяч экземпляров. Церемония памятного гашения конверта прошла 19 сентября 2025 года в конгресс-центре «Измайлово Гамма-Дельта» перед начал','/index.php/news/vse-novosti/1017-konvert-v-chest-120-letiya-rossijskikh-profsoyuzov-postupil-v-pochtovoe-obrashchenie','/images/news/konvert.png');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1020-sdayutsya-v-arendu-kvartiry-v-tsentre-khabarovska','Сдаются в аренду квартиры в центре Хабаровска','2020-01-01','novosti','[]','Сдаются в аренду двухкомнатные квартиры в районе Хабаровских городских прудов. --> --> --> --> --> --> --> --> --> Смотреть встроенную онлайн галерею в: https://habprof.ru/index.php/news/vse-novosti/1020-sdayutsya-v-arendu-kvartiry-v-tsentre-khabarovska#sigProIda68e2e327f Дом расположен по адресу: улица Мухина, дом 7 (пересечение улицы Пушкина и Уссурийского бульвара. В пешей доступности Платинум ','/index.php/news/vse-novosti/1020-sdayutsya-v-arendu-kvartiry-v-tsentre-khabarovska','/images/news/1.JPG');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1023-nagrady-vruchili-aviastroitelyam-k-yubileyu-ppoo-knaaz','Награды вручили авиастроителям к юбилею ППОО КнААЗ','2020-01-01','novosti','[]','В октябре свой 90-летний юбилей отметила первичная профсоюзная общественная организация Комсомольского-на-Амуре авиационного завода им. Ю.А.Гагарина. Всего наградами различного уровня, в связи с юбилейной датой, были отмечены более 100 членов профсоюзной организации. В том числе от Центрального комитета Российского профсоюза трудящихся авиационной промышленности (Профавиа) за заслуги перед профсою','/index.php/news/vse-novosti/1023-nagrady-vruchili-aviastroitelyam-k-yubileyu-ppoo-knaaz','/images/news/90-let-ppoo-knaaz.jpg');
