INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1028-litsa-profsoyuzov-dashko-elena-andreevna','Лица Профсоюзов: Дашко Елена Андреевна','2020-01-01','novosti','[]','Дашко Елена Андреевна - председатель первичной профсоюзной организации АО «Хабаровский речной торговый порт». Елена Андреевна вступила в ряды профсоюза в 1985 году с первых дней работы в порту. Всегда была активным членом профсоюза, возглавляла цеховой комитет на грузовом районе «Ветка», была заместителем председателя первичной профсоюзной организации, а в 2015 году была назначена на пост председа','/index.php/news/vse-novosti/1028-litsa-profsoyuzov-dashko-elena-andreevna',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1029-litsa-profsoyuzov-garnaga-anastasiya-filippovna','Лица Профсоюзов: Гарнага Анастасия Филипповна','2020-01-01','novosti','[]','Гарнага Анастасия Филипповна – председатель инновационного сектора профсоюзного комитета работников Тихоокеанского государственного университета, доцент Высшей школы архитектуры и градостроительства. «Профсоюз для меня – мощный инструмент объединения людей, которые нуждаются в помощи, или могут и хотят ее оказать. Сила и мощь как раз в солидарности, которая позволяет защищать интересы работников, ','/index.php/news/vse-novosti/1029-litsa-profsoyuzov-garnaga-anastasiya-filippovna',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1032-liderom-regionalnogo-profsoyuza-zdravookhraneniya-izbrana-olga-admidina','Лидером регионального профсоюза здравоохранения вновь избрана Ольга Адмидина','2020-01-01','novosti','[]','Такое решение единогласно приняли делегаты 32 отчетно-выборной конференции краевой организации. Работа региональной организации за отчетный период была признана удовлетворительной. За минувшую пятилетку в краевом комитете рассмотрено 440 письменных и 1787 устных обращений членов профсоюза, по которым оказана консультативная и практическая помощь. Кроме того, в ходе конференции были награждены дипл','/index.php/news/vse-novosti/1032-liderom-regionalnogo-profsoyuza-zdravookhraneniya-izbrana-olga-admidina','/images/news/photo_5253852971886381992_y.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1035-litsa-profsoyuzov-stonoga-konstantin-anatolevich','Лица Профсоюзов: Стонога Константин Анатольевич','2020-01-01','novosti','[]','Стонога Константин Анатольевич - испытатель агрегатов, приборов и чувствительных элементов отдела испытаний, исследований и надежности (ОИИН) филиала ПАО «ОАК»-КнААЗ» им. Ю.А. Гагарина. Председатель профсоюзного комитета отдела (ОИИН). Константин Анатольевич уже более 20 лет является членом первичной профсоюзной общественной организации КнААЗ им. Ю. А. Гагарина. В профсоюз вступил по настоятельной','/index.php/news/vse-novosti/1035-litsa-profsoyuzov-stonoga-konstantin-anatolevich',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1039-litsa-profsoyuzov-nozdratenko-svetlana-efimovna','Лица Профсоюзов: Ноздратенко Светлана Ефимовна','2020-01-01','novosti','[]','Ноздратенко Светлана Ефимовна - председатель городской профсоюзной организации города Комсомольска-на-Амуре Хабаровской краевой организации профсоюза работников жизнеобеспечения. Свой путь в профсоюзе Светлана Ефимовна начала в августе 1986 года в должности председателя первичной профсоюзной организации Горбыткомбината города Комсомольска-на-Амуре. С 1990 года является членом краевого комитета Хаб','/index.php/news/vse-novosti/1039-litsa-profsoyuzov-nozdratenko-svetlana-efimovna',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1041-litsa-profsoyuzov-chikicheva-ekaterina-gennadevna','Лица Профсоюзов: Чикичева Екатерина Геннадьевна','2020-01-01','novosti','[]','Чикичева Екатерина Геннадьевна - п редседатель первичной профсоюзной организации ФБУ «Администрация Амурводпуть» - «Хабаровский район внутренних водных путей». Председателем Екатерина Геннадьевна была избрана три года назад. Благодаря своим профессиональным знаниям в области юриспруденции, она успешно защищает права членов профсоюза. Первичная профсоюзная организация насчитывает 38 человек, но это','/index.php/news/vse-novosti/1041-litsa-profsoyuzov-chikicheva-ekaterina-gennadevna',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1042-litsa-profsoyuzov-dergaeva-anna-vitalevna','Лица Профсоюзов: Дергаева Анна Витальевна','2020-01-01','novosti','[]','Дергаева Анна Витальевна - медицинская сестра терапевтического отделения госпиталя ФКУЗ «Медико-санитарной части МВД России по Хабаровскому краю». Обладает большим опытом работы и практическими знаниями в своей профессиональной деятельности. На протяжении 37 лет Анна Витальевна является активным членом первичной профсоюзной организации ФКУЗ «Медико-санитарной части МВД России по Хабаровскому краю»','/index.php/news/vse-novosti/1042-litsa-profsoyuzov-dergaeva-anna-vitalevna',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1043-litsa-profsoyuzov-sukhova-svetlana-pavlovna','Лица Профсоюзов: Сухова Светлана Павловна','2020-01-01','novosti','[]','Сухова Светлана Павловна - специалист высшей школы кибернетики и цифровых технологий Тихоокеанского государственного университета. Свой профсоюзный путь Светлана Павловна начала профгруппоргом кафедры. Сегодня она секретарь профсоюзного комитета работников университета. У Светланы Павловны очень ответственное поручение - именно она держит в порядке всю документацию заседаний, оформляет мотивирован','/index.php/news/vse-novosti/1043-litsa-profsoyuzov-sukhova-svetlana-pavlovna',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1044-litsa-profsoyuzov-zakharova-irina-irkingalievna','Лица Профсоюзов: Захарова Ирина Иркингалиевна','2020-01-01','novosti','[]','Захарова Ирина Иркингалиевна - ведущий инженер-конструктор, отдел главного технолога филиала ПАО «ОАК»-КнААЗ им. Ю.А.Гагарина. Ирина Иркингалиевна более 14 лет состоит в первичной профсоюзной общественной организации КнААЗ им. Ю.А.Гагарина. Сегодня является председателем цехового комитета и членом комиссии общественного контроля за работой подразделений социальной сферы. Её вклад в работу профсоюз','/index.php/news/vse-novosti/1044-litsa-profsoyuzov-zakharova-irina-irkingalievna',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1045-litsa-profsoyuzov-kayasheva-irina-ivanovna','Лица Профсоюзов: Каяшева Ирина Ивановна','2020-01-01','novosti','[]','Каяшева Ирина Ивановна работает - учителем начальных классов в МБОУ СОШ села Маяк Нанайского муниципального района. Свой трудовой путь Ирина Ивановна начала с 1984 года, а членом профсоюза стала еще раньше - в 1980 году. Ирина Ивановна зарекомендовала себя добросовестным, ответственным и творческим педагогом. Её смело можно назвать педагогом-новатором: она постоянно внедряет в свою работу различны','/index.php/news/vse-novosti/1045-litsa-profsoyuzov-kayasheva-irina-ivanovna',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1051-litsa-profsoyuzov-dunnikova-olga-sergeevna','Лица Профсоюзов: Дунникова Ольга Сергеевна','2020-01-01','novosti','[]','Дунникова Ольга Сергеевна – председатель Комсомольской-на-Амуре городской организации Профсоюза работников народного образования и науки РФ. Ольга Сергеевна уже более 25 лет трудится в системе образования Комсомольска‑на‑Амуре. С 2016 года она возглавляет городскую организацию Общероссийского Профсоюза образования. Активно участвует в работе профсоюзных и общественных институтов города и края. Осо','/index.php/news/vse-novosti/1051-litsa-profsoyuzov-dunnikova-olga-sergeevna',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1052-litsa-profsoyuzov-kukhtina-liliya-gennadevna','Лица Профсоюзов: Кухтина Лилия Геннадьевна','2020-01-01','novosti','[]','Кухтина Лилия Геннадьевна – учитель начальных классов, председатель первичной профсоюзной организации Муниципального общеобразовательного учреждения гимназия № 45 г. Комсомольск-на-Амуре. Как педагог Лилия Геннадьевна демонстрирует высокий уровень профессионализма: за годы работы она выпустила из начальной школы не одно поколение учащихся. Её деятельность характеризуется: В качестве председателя п','/index.php/news/vse-novosti/1052-litsa-profsoyuzov-kukhtina-liliya-gennadevna',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1054-litsa-profsoyuzov-lebedev-viktor-sergeevich','Лица Профсоюзов: Лебедев Виктор Сергеевич','2020-01-01','novosti','[]','Виктор Сергеевич Лебедев – председатель первичной профсоюзной организации ФБУ «Администрация Амурводпуть». Был избран восемь лет назад. За время своей работы проявил себя как ответственный, инициативный и целеустремленный руководитель, отстаивающий интересы членов профсоюза. Активно участвует в разработке и реализации коллективного договора, добиваясь улучшения условий труда и социальной защиты ра','/index.php/news/vse-novosti/1054-litsa-profsoyuzov-lebedev-viktor-sergeevich',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1055-litsa-profsoyuzov-pavel-evgenevich-mysin','Лица Профсоюзов: Павел Евгеньевич Мысин','2020-01-01','novosti','[]','Павел Евгеньевич Мысин – авторитетный руководитель, талантливый организатор и профессионал с 35 – летним стажем работы на руководящих должностях законодательной и исполнительной власти города Хабаровска и Хабаровского края, с июля 2014 года – кандидат экономических наук. С июля 2016 года по настоящее время директор КГБ ПОУ «Хабаровский автомеханический колледж (Автодор)». В рамках достижения высок','/index.php/news/vse-novosti/1055-litsa-profsoyuzov-pavel-evgenevich-mysin',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1056-litsa-profsoyuzov-palousov-andrej-arkadevich','Лица Профсоюзов: Палоусов Андрей Аркадьевич','2020-01-01','novosti','[]','Палоусов Андрей Аркадьевич – главный специалист, председатель первичной профсоюзной организации Управления образования администрации города Комсомольска-на-Амуре Хабаровского края. Палоусов Андрей Аркадьевич – опытный специалист в сфере образования, чей профессиональный стаж превышает 30 лет. Деятельность Андрея Аркадьевича направлена на повышение качества кадрового потенциала образовательной сист','/index.php/news/vse-novosti/1056-litsa-profsoyuzov-palousov-andrej-arkadevich',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1057-koordinatsionnyj-sovet-sozdan-v-bikinskom-okruge','Координационный совет создан в Бикинском округе','2020-01-01','novosti','[]','Хабаровское Профобъединение расширяет свое представительство в муниципалитетах региона. В Бикинском округе создан координационный совет, который будет работать по следующим направлениям: создание новых профсоюзных организаций; --> --> --> Смотреть встроенную онлайн галерею в: https://habprof.ru/index.php/news/vse-novosti/1057-koordinatsionnyj-sovet-sozdan-v-bikinskom-okruge#sigProId1ca4da81bf Кром','/index.php/news/vse-novosti/1057-koordinatsionnyj-sovet-sozdan-v-bikinskom-okruge','/images/news/photo_5233615219131618148_y.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1058-amurskij-patronnyj-zavod-vympel-imeni-p-v-finogenova-otmechaet-50-letnij-yubilej','«Амурский патронный завод "Вымпел" имени П. В. Финогенова» отмечает 50-летний юбилей','2020-01-01','novosti','[]','Галина Казанцева — председатель первичной профсоюзной организации "Вымпел", рассказала о своем трудовом пути и развитии организации медиацентру "Время Молодых". Галина Леонтьевна Казанцева — председатель первичной профсоюзной организации "Вымпел", лидер краевого масштаба и председатель координационного совета профсоюзов Амурского района. Её путь — живая история патриотизма и преданности своему дел','/index.php/news/vse-novosti/1058-amurskij-patronnyj-zavod-vympel-imeni-p-v-finogenova-otmechaet-50-letnij-yubilej',NULL);
