INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1082-generalnyj-sovet-fnpr-obsudil-dostizheniya-i-aktualnye-zadachi-profsoyuzov-rossii','Генеральный совет ФНПР обсудил достижения и актуальные задачи профсоюзов России','2020-01-01','novosti','[]','Актуальные задачи Федерации Независимых Профсоюзов России, основные профсоюзные достижения за прошлый год и концепция Генерального соглашения стали основными темами заседания Генсовета ФНПР, которое состоялось 20 мая в Москве. Участие в мероприятии приняли более 150 профлидеров со всей России, в том числе председатель Хабаровского Профобъединения Галина Кононенко. С докладом, посвященным основным ','/index.php/news/vse-novosti/1082-generalnyj-sovet-fnpr-obsudil-dostizheniya-i-aktualnye-zadachi-profsoyuzov-rossii','/images/news/Gensovet.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1090-fizkulturno-sportivnyj-festival-azart-zdorove-otdykh-zavershilsya-v-khabarovske','Физкультурно-спортивный фестиваль «Азарт. Здоровье. Отдых» завершился в Хабаровске','2020-01-01','novosti','[]','В этом году соревнования прошли уже в 32 раз и были посвящены Году трудового единства и солидарности, и Году спорта в Хабаровском крае. Участниками фестиваля стали около 700 любителей спорта Хабаровского края. В течение трех дней они состязались в 11 видах спорта: баскетбол 3х3, волейбол, гиревой спорт, дартс, легкая атлетика, мини-футбол, настольный теннис, плавание, перетягивание каната, шахматы','/index.php/news/vse-novosti/1090-fizkulturno-sportivnyj-festival-azart-zdorove-otdykh-zavershilsya-v-khabarovske',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1092-startoval-priem-zayavok-na-konkurs-luchshij-nastavnik-sredi-chlenskikh-organizatsij-khabarovskogo-profob-edineniya','Стартовал прием заявок на конкурс «Лучший наставник» среди членских организаций Хабаровского Профобъединения','2020-01-01','novosti','[]','Цель конкурса – повышение престижа наставничества в организациях всех форм собственности, развитие традиций наставничества, сохранение и развитие профессиональной культуры, создание привлекательных условий труда для молодых работников, закрепление кадров в организациях. Номинации конкурса: лучший наставник в организации производственной / непроизводственной сферы, лучший наставник – профЛидер. Кон','/index.php/news/vse-novosti/1092-startoval-priem-zayavok-na-konkurs-luchshij-nastavnik-sredi-chlenskikh-organizatsij-khabarovskogo-profob-edineniya',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1096-s-dnjom-gosudarstvennogo-flaga-rossijskoj-federatsii','С Днём Государственного флага Российской Федерации!','2020-01-01','novosti','[]','Сегодня мы чествуем один из главных символов нашей страны. Триколор – это отражение нашей истории, символ единства, мужества и трудовой доблести миллионов россиян. Для профсоюзного движения Хабаровского края этот праздник имеет особое значение. Профсоюзы – это люди труда, те, кто своим ежедневным упорством, мастерством и преданностью делу строит будущее нашего региона и всей страны. Под знаменем н','/index.php/news/vse-novosti/1096-s-dnjom-gosudarstvennogo-flaga-rossijskoj-federatsii','/images/news/i-1.webp');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('194-my-v-sotsialnykh-setyakh','Мы — в социальных сетях','2020-01-01','novosti','[]','Хабаровское профобъединение ведёт политику открытости и доступности к нашим информационным ресурсам — для всех членов профсоюзов и их организаций, профсоюзных лидеров и социальных партнёров, общества в целом. Мы — за открытый диалог и конструктивное обсуждение всех вопросов в сфере трудовых отношений, социального и экономического развития во благо человека труда, жителей Хабаровского края и гражда','/index.php/news/vse-novosti/194-my-v-sotsialnykh-setyakh','/images/news/habprof-smm.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('197-programma-fnpr-za-spravedlivuyu-ekonomiku-v-dejstvii','Программа ФНПР "За справедливую экономику!" в действии','2020-01-01','podderzhka','[]','Благополучие человека – цель экономики и её развития Современное рыночное хозяйство построено на взаимоотношениях труда и капитала, работника и работодателя. Их объединяют общие цели – производство товаров и услуг, обеспечение его эффективности и безопасности, поддержание устойчивого потребительского спроса. Но некоторые существенные интересы труда и капитала находятся в неизбежном противоречии. С','/index.php/news/vse-novosti/197-programma-fnpr-za-spravedlivuyu-ekonomiku-v-dejstvii',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('199-prezidium-kraevogo-komiteta-profsoyuza-rabotnikov-zhizneobespecheniya-podvel-itogi-2022-goda','Президиум краевого комитета профсоюза работников жизнеобеспечения подвел итоги 2022 года','2020-01-01','novosti','[]','Очередное заседание президиума Хабаровского профсоюза работников жизнеобеспечения прошло 20 апреля в здании Хабаровского Профобъединения. В ходе заседания члены президиума рассмотрели вопросы по подведению итогов финансовой работы краевого комитета за 2022 год. Помимо этого, они обсудили постановления об участии краевого комитета: в коллективных действиях профсоюзов 1 мая, в соревнованиях 29 физку','/index.php/news/vse-novosti/199-prezidium-kraevogo-komiteta-profsoyuza-rabotnikov-zhizneobespecheniya-podvel-itogi-2022-goda','/images/news/prezidium-jizneobespechenie-aprel-2023.jpg');
