INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('218-minuta-molchaniya-projdjot-v-khabarovskom-krae','"Минута молчания" пройдёт в Хабаровском крае','2020-01-01','novosti','[]','Уже завтра, 22 июня, в День памяти и скорби одновременно по всей стране пройдет акция «Минута молчания» в память о тех, кто героически сражался за Родину в годы Великой Отечественной войны. Хабаровский край примет участие в акции в 19:15 по местному времени. Ровно на минуту будет приостановлено вещание в эфире телевидения и радио, движение общественного транспорта, работа касс в торговых центрах и','/index.php/news/vse-novosti/218-minuta-molchaniya-projdjot-v-khabarovskom-krae',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('222-624-proforganizatsii-dnr-i-lnr-poluchat-dostup-k-svezhej-profsoyuznoj-presse','624 профорганизации ДНР и ЛНР получат доступ к свежей профсоюзной прессе','2020-01-01','novosti','[]','С 20 апреля по 19 июня 2023 года газета “Солидарность” проводила конкурс-акцию “Прояви солидарность - подпиши на “Солидарность”, цель которой - помощь и поддержка профорганизаций ДНР и ЛНР в доступе к профсоюзной информации. Для участия необходимо было оформить подписку для одной из профсоюзных организаций ЛНР или ДНР на электронную версию газеты “Солидарность” сроком на год. Всего в конкурсе прин','/index.php/news/vse-novosti/222-624-proforganizatsii-dnr-i-lnr-poluchat-dostup-k-svezhej-profsoyuznoj-presse',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('224-khabarovskij-kraevoj-profsoyuz-rabotnikov-zhizneobespecheniya-prinyal-uchastie-v-meropriyatiyakh-obshcherossijskogo-','Хабаровский краевой профсоюз работников жизнеобеспечения принял участие в мероприятиях Общероссийского профсоюза отрасли','2020-01-01','novosti','[]','С 22 по 26 мая в Москве прошли заседания Центральной контрольно-ревизионной комиссии Профсоюза, Президиума и Пленума, совещания по актуальным вопросам в сфере жилищно-коммунального хозяйства, а также семинары по вопросам соблюдения бухгалтерского и налогового законодательства. В мероприятиях, проводимых Центральным комитетом Общероссийского профсоюза работников жизнеобеспечения, приняли участие пр','/index.php/news/vse-novosti/224-khabarovskij-kraevoj-profsoyuz-rabotnikov-zhizneobespecheniya-prinyal-uchastie-v-meropriyatiyakh-obshcherossijskogo-profsoyuza-otrasli','/images/news/1.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('225-terkom-profsoyuza-aviarabotnikov-provel-ocherednoe-zasedanie','Терком профсоюза авиаработников провел очередное заседание','2020-01-01','novosti','[]','Четвертое заседание Дальневосточной территориальной организации Общероссийского профсоюза авиационных работников прошло сегодня, 28 апреля. Ключевой темой стал разговор о мерах по развитию колдоговорного регулирования на предприятиях Дальневосточного региона. С основным докладом выступила председатель организации Светлана Молчанова. В прениях по докладу выступили семь председателей первичных орган','/index.php/news/vse-novosti/225-terkom-profsoyuza-aviarabotnikov-provel-ocherednoe-zasedanie','/images/news/dsc03568.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('226-pozdravlenie-s-1-i-9-maya','Поздравление с 1 и 9 мая!','2020-01-01','novosti','[]','С наступающими праздниками поздравила председатель Хабаровской краевой организации общероссийского профсоюза работников автомобильного транспорта и дорожного хозяйства. От имени Хабаровской краевой организации общероссийского профсоюза работников автомобильного транспорта и дорожного хозяйства сердечно поздравляю вас с Первомаем - Международным днем солидарности трудящихся, праздником Весны и Труд','/index.php/news/vse-novosti/226-pozdravlenie-s-1-i-9-maya',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('227-khabarovskogo-kraya','Профсоюзы Хабаровского края почтили память погибших в ВОВ минутой молчания','2020-01-01','novosti','[]','Всероссийские акции "Минута молчания" и "Свеча памяти" прошли вчера, 22 июня, в День памяти и скорби. Территория перед зданием Хабаровского Профобъединения стала местом, где горожане собрались вспомнить героев, сражавшихся за свободу и независимость нашей Родины. 82 года назад в нашу страну вторглись фашистские захватчики. Эта война унесла десятки миллионов человеческих жизней. Жизней тех, кто шел','/index.php/news/vse-novosti/227-khabarovskogo-kraya',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('229-zayavlenie-federatsii-nezavisimykh-profsoyuzov-rossii','Заявление Федерации Независимых Профсоюзов России','2020-01-01','novosti','[]','Как и сто лет назад в результате вооруженного мятежа наша страна оказалась на пороге гражданского противостояния. В этой ситуации Федерация Независимых Профсоюзов России, как крупнейшая общественная организация страны, призывает всех граждан страны сплотиться вокруг законно избранного Президента и Верховного Главнокомандующего. Сейчас против нас воюет финансовый капитал хищнического империалистиче','/index.php/news/vse-novosti/229-zayavlenie-federatsii-nezavisimykh-profsoyuzov-rossii','/images/news/zayavlenie-fnpr.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('230-fnpr-initsiirovala-rasshirenie-lgot-i-garantij-dlya-rabotayushchej-molodezhi','ФНПР инициировала расширение льгот и гарантий для работающей молодежи','2020-01-01','molodezh','[]','Федерация независимых профсоюзов России предлагает расширить понятие «молодой специалист» и внести новое - «молодой работник». Предложения ФНПР учтены в законопроекте, которым планируется внести изменения в федеральный закон о молодёжной политике. Вчера законопроект был внесен в Госдуму. «ФНПР предлагает изменить - расширить - трактовку понятия «молодой специалист», чтобы усилить поддержку молодеж','/index.php/news/vse-novosti/230-fnpr-initsiirovala-rasshirenie-lgot-i-garantij-dlya-rabotayushchej-molodezhi',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('233-poryadka-12-mln-rossiyan-trudyatsya-neofitsialno','Порядка 12 млн россиян трудятся неофициально','2020-01-01','novosti','[]','Около 6 млн работающих россиян получают минимальный размер оплаты труда, а 12 млн работают без заключения трудовых договоров, такие данные привела вице-премьер РФ Татьяна Голикова на Петербургском международном экономическом форуме. «Соглашаясь на зарплату «в конверте» работник лишает себя социально-трудовых гарантий, отказывается от безопасности и стабильности. К сожалению, нередки случаи, когда ','/index.php/news/vse-novosti/233-poryadka-12-mln-rossiyan-trudyatsya-neofitsialno',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('234-vozmozhnost-oformleniya-lgot-dlya-grazhdan-predpensionnogo-vozrasta-v-rossii','Возможность оформления льгот для граждан предпенсионного возраста в России','2020-01-01','novosti','[]','Федерация независимых профсоюзов России обращает внимание членских организаций на возможность оформления льгот для граждан предпенсионного возраста. Пенсионный возраст постепенно повышается, для мужчин до 65 лет, для женщин до 60 лет. Но возраст, дающий право на получение социальных услуг, остается прежним - 55 лет для женщин и 60 лет для мужчин. Он называется предпенсионным. Статус предпенсионера','/index.php/news/vse-novosti/234-vozmozhnost-oformleniya-lgot-dlya-grazhdan-predpensionnogo-vozrasta-v-rossii',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('264-v-komsomolske-na-amure-proshjol-fleshmob-v-podderzhku-pervomajskogo-avtoprobega','В Комсомольске-на-Амуре прошёл флешмоб в поддержку первомайского автопробега','2020-01-01','novosti','[]','Пробег был рганизован Федерацией независимых профсоюзов России под девизом «ZA Мир! Труд! Май! / ZA мир без нацизма!» Участники флешмоба выстроили свои автомобили в форме буквы «V» на парковке у драматического театра. Помимо этого, профсоюзные активисты сформировали строй в виде буквы «Z». «Цель нашей акции — поддержка президента в принятых решениях, а также поддержка наших ребят, которые участвую','/index.php/news/vse-novosti/264-v-komsomolske-na-amure-proshjol-fleshmob-v-podderzhku-pervomajskogo-avtoprobega',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('265-rabochaya-gruppa-fnpr-po-problemam-severa-provela-rasshirennoe-zasedanie-v-khabarovske','Рабочая группа ФНПР по проблемам Севера провела расширенное заседание в Хабаровске','2020-01-01','novosti','[]','Расширенное заседание рабочей группы ФНПР по проблемам северных территорий прошло совместно с представителями профсоюзов, исполнительной и законодательной власти, прокуратуры, работодателей, общественности, уполномоченные по правам человека субъектов РФ - Дальневосточного, Сибирского, Северо-Западного федеральных округов. Совещание проходило в Доме официальных приёмов Правительства Хабаровского кр','/index.php/news/vse-novosti/265-rabochaya-gruppa-fnpr-po-problemam-severa-provela-rasshirennoe-zasedanie-v-khabarovske',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('267-na-sobstvennom-primere','На собственном примере','2020-01-01','novosti','[]','Председатель Хабаровского Профобъединения Галина Кононенко прошла ревакцинацию от Covid-19. Повторная вакцинация призвана поддержать и усилить поствакцинальный иммунный ответ организма, так как со временем он ослабевает. Первые две дозы вакцины Галина Анатольевна получила в январе и феврале этого года. «Ежедневно я контактирую с большим количеством людей и не хочу подвергать окружающих риску. Я не','/index.php/news/vse-novosti/267-na-sobstvennom-primere',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('269-proflider-khabarovskogo-kraya-vnov-vozglavila-obshchestvennuyu-palatu-kraya','Профлидер Хабаровского края вновь возглавила Общественную палату края','2020-01-01','novosti','[]','Председатель Союза «Хабаровское краевое объединение организаций профсоюзов» Галина Кононенко вновь возглавила Общественную палату края. Такое решение единогласно приняли члены палаты в этот понедельник, 28 июня. Состав Общественной палаты меняется раз в три года, на этот раз он обновлен на две трети: 22 человека из 33 вошли в нее впервые. В этот раз в составе общественного органа представители сра','/index.php/news/vse-novosti/269-proflider-khabarovskogo-kraya-vnov-vozglavila-obshchestvennuyu-palatu-kraya',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('275-s-prazdnikom-lyubimaya-strana','С праздником, любимая страна!','2020-01-01','novosti','[]','Хабаровское Профобъединение поздравляет всех граждан нашей огромной державы с Днём России! Днём могучей страны, в который мы живём, трудимся на ее благо, любим, создаём семьи и воспитываем детей. Пусть в душе каждого гражданина будет место для любви к своей Родине! Пусть процветает великая страна! Пусть в небе ярко светит солнце! Мира, добра и благополучия в каждый дом! --> Версия для слабовидящих','/index.php/news/vse-novosti/275-s-prazdnikom-lyubimaya-strana','/images/news/den-rossii.jpg');
