INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('277-s-dnem-medika','С Днем медика!','2020-01-01','novosti','[]','Поздравляем с профессиональным праздником тех людей, чей белый халат служит для пациентов символом надежды и помощи. Желаем всем, кто посвятил свою жизнь медицине, терпения в вашем нелегком деле, благополучия и счастья! Вы отдаете частицу своего сердца каждому пациенту, так пусть ваше благородное служение будет вознаграждено сполна! Вы ежедневно боретесь за чье-то здоровье, так пусть же ваше здоро','/index.php/news/vse-novosti/277-s-dnem-medika',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('279-s-yubileem-asz','С юбилеем, АСЗ!','2020-01-01','novosti','[]','Ровно 90 лет назад был заложен первый цех Амурского судостроительного завода. За эти годы был пройден славный пусть становления, расцвета, преодоления трудностей, выдающихся трудовых успехов и впечатляющих достижений. Сегодня АСЗ – это крупнейшее судостроительное предприятие на Дальнем Востоке и один из флагманов промышленности страны. За свою почти вековую историю завод выпустил более 300 корабле','/index.php/news/vse-novosti/279-s-yubileem-asz','/images/news/asz.jpg');
