INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('747-svyshe-1000-chelovek-v-proshlom-godu-pomogli-vosstanovit-na-rabote-profsoyuznye-yuristy','Свыше 1000 человек в прошлом году помогли восстановить на работе профсоюзные юристы','2020-01-01','novosti','[]','Свыше 1000 членов профсоюза в прошлом году восстановлено на работе. 500 нерадивых работодателей за нарушение трудового законодательства привлечено к уголовной и административной ответственности, 17 из них дисквалифицировано. Таков итог правозащитной работы профсоюзных юристов Федерации независимых профсоюзов России за 2013 год. Как сообщает департамент общественных связей ФНПР, профсоюзный контрол','/index.php/news/vse-novosti/28-system-category/747-svyshe-1000-chelovek-v-proshlom-godu-pomogli-vosstanovit-na-rabote-profsoyuznye-yuristy',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('280-s-dnjom-rozhdeniya-gorod-yunosti','С Днём рождения, город Юности!','2020-01-01','novosti','[]','Не только День России, но и свой День Рождения сегодня отмечает Комсомольск-на-Амуре. Ровно 91 год назад был основан город Юности. Сегодня это промышленно-индустриальный центр Дальнего Востока. В 2021 году Комсомольску было присвоено почётное звание «Город трудовой доблести» за значительный вклад жителей в достижение победы в Великой Отечественной войне. В 1941-1945 годы город стал форпостом оборо','/index.php/news/vse-novosti/280-s-dnjom-rozhdeniya-gorod-yunosti','/images/news/den-goroda-kms.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('282-proflider-kraya-posetila-zavody-asz-i-knaaz','Профлидер края посетила заводы КнААЗ и АСЗ','2020-01-01','novosti','[]','Профлидер Хабаровского края Галина Кононенко встретилась с профсоюзным активом Комсомольского-на-Амуре авиационного завода и Амурского судостроительного завода в рамках рабочего визита в город Юности. Ключевой темой разговоров стало вовлечение в организацию новых членов профсоюза. Также обсудили повышение привлекательности профсоюзного членства для молодежи. Представители «первичек» озвучили свои ','/index.php/news/vse-novosti/282-proflider-kraya-posetila-zavody-asz-i-knaaz','/images/news/Кнааз.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('284-dorogie-khabarovchane-pozdravlyaem-s-yubileem-nashego-slavnogo-goroda','Дорогие Хабаровчане, поздравляем с юбилеем нашего славного города!','2020-01-01','novosti','[]','Сегодня краевой столице исполнилось 165 лет. Хабаровск – это, прежде всего, про людей. Про тех, кто здесь родился и вырос. Про тех, кто переехал сюда по работе или по любви. Каждый житель города вносит свой вклад в его развитие. Больше полутора веков прошло со дня основания когда-то военного пункта Хабаровка, и с каждым днём он растёт и преображается. Гордо раскинулся наш город на берегу Амура, об','/index.php/news/vse-novosti/284-dorogie-khabarovchane-pozdravlyaem-s-yubileem-nashego-slavnogo-goroda','/images/news/yubilej-khabarovska.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('285-pravitelstvo-rossii-obnovilo-poryadok-ispolzovaniya-dopolnitelnykh-vykhodnykh-dnej-dlya-roditelej-detej-s-invalidnos','Правительство России обновило порядок использования дополнительных выходных дней для родителей детей с инвалидностью','2020-01-01','podderzhka','[]','Согласно опубликованному постановлению, теперь дополнительные нерабочие дни можно накапливать и использовать как дополнительный оплачиваемый отпуск. Предварительно сотрудник должен будет согласовать с работодателем его даты и подать заявление в отдел кадров. Также продолжительность одного отпуска не должна превышать 24 дня. Кроме того, предусмотрена возможность предоставления одному из родителей д','/index.php/news/vse-novosti/285-pravitelstvo-rossii-obnovilo-poryadok-ispolzovaniya-dopolnitelnykh-vykhodnykh-dnej-dlya-roditelej-detej-s-invalidnostyu',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('292-s-dnem-velikoj-pobedy','С Днем Великой Победы!','2020-01-01','novosti','[]','Всё дальше в прошлое уходит одна из самых страшных страниц истории нашего Отечества. Но нельзя забывать, сколько слёз и крови было пролито, чтобы подарить свободу и независимость нашей Родине. 78 лет прошло с того майского дня 45-го, а сердце всё так же ликует от радости и сжимается от печали. Девятое число стало символом несгибаемого духа, единства и героизма нашего народа! Сегодня и каждый день ','/index.php/news/vse-novosti/292-s-dnem-velikoj-pobedy','/images/news/den-pobedy.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('304-mot-priznala-nash-trudovoj-kodeks-luchshim-iz-prinyatykh-za-poslednie-desyatiletiya','МОТ признала наш Трудовой кодекс лучшим из принятых за последние десятилетия','2020-01-01','novosti','[]','Об этом председатель ФНПР заявил в ходе четвертой международной научно-практической конференции «Смирновские чтения». Мероприятие прошло в Академии труда и социальных отношений и совпало с юбилеем Трудового кодекса. «Международная организация труда признала наш Трудовой кодекс лучшим из принятых за последние десятилетия», — заявил в ходе конференции председатель Федерации независимых профсоюзов Ро','/index.php/news/vse-novosti/304-mot-priznala-nash-trudovoj-kodeks-luchshim-iz-prinyatykh-za-poslednie-desyatiletiya',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('305-vosmuyu-godovshchinu-krymskoj-vesny-otmetili-v-khabarovske','Восьмую годовщину "Крымской весны" отметили в Хабаровске','2020-01-01','novosti','[]','Митинг-концерт, посвященный годовщине официального вхождения Крыма в состав России, прошел в Хабаровском краевом Дворце профсоюзов сегодня, 18 марта. Творческие коллективы региона выступили с народными песнями и танцами, помимо этого, к зрителям обратились руководители правительства края, общественных организаций и лидеры общественного мнения. « Героизм и самоотверженность в генах нашего народа. Я','/index.php/news/vse-novosti/305-vosmuyu-godovshchinu-krymskoj-vesny-otmetili-v-khabarovske','/images/news/krymskaya-vesna-2022.jpg');
