INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('313-mezhvuzovskij-kampus-postroyat-v-khabarovskom-krae','Межвузовский кампус построят в Хабаровском крае','2020-01-01','novosti','[]','Такое решение было принято на XXVI Международном экономическом форуме в Санкт-Петербурге. В рамках мероприятия было подписано соглашение о создании пяти студенческих кампусов мирового уровня на 15 тысяч мест для студентов и преподавателей. Современные объекты появятся в Хабаровском крае и Архангельской, Ивановской, Самарской, Сахалинской областях. «Межвузовский кампус – это многофункциональная эко','/index.php/news/vse-novosti/313-mezhvuzovskij-kampus-postroyat-v-khabarovskom-krae',NULL);
