INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('369-budte-v-kurse-aktualnykh-profsoyuznykh-novostej-strany','Будьте в курсе актуальных профсоюзных новостей страны','2020-01-01','novosti','[]','Дорогие коллеги! Профсоюзные активисты! Подписывайтесь на официальные страницы Федерации независимых профсоюзов России в Telegram и ВКонтакте . Там собрана информация о социально-трудовых правах работников, последних изменениях в трудовом законодательстве, опыте профсоюзных организаций по защите интересов трудящихся. Будьте в курсе актуальных профсоюзных новостей! Знайте свои трудовые права! Участ','/index.php/news/vse-novosti/369-budte-v-kurse-aktualnykh-profsoyuznykh-novostej-strany','/images/news/photo_5869342104889700626_x.jpg');
