INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('384-s','С наступающим праздником, работники нефтяной и газовой промышленности!','2020-01-01','novosti','[]','Поздравление председателя Хабаровской краевой организации профсоюза работников жизнеобеспечения Натальи Плаксиной. Уважаемые работники и ветераны нефтяной, газовой и топливной промышленности! От имени Хабаровской краевой организации профсоюза работников жизнеобеспечения поздравляю вас с наступающим профессиональным праздником! Нефтегазовая отрасль является важнейшей в российской экономике, прочным','/index.php/news/vse-novosti/384-s','/images/news/attachment-1.png');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('386-profsoyuznykh-aktivistov-veterinarnoj-sluzhby-nagradili-v-khabarovske','Профсоюзных активистов ветеринарной службы наградили в Хабаровске','2020-01-01','novosti','[]','В связи с профессиональным праздником почётными грамотами Хабаровского Профобъединения были награждены восемь сотрудников краевой станции по борьбе с болезнями животных. Все они внесли большой вклад в защиту трудовых, социально-экономических прав и интересов членов профсоюза своей организации. "Напряженный труд ветеринарных работников неразрывно связан со стабильным развитием животноводства и увел','/index.php/news/vse-novosti/386-profsoyuznykh-aktivistov-veterinarnoj-sluzhby-nagradili-v-khabarovske','/images/news/92b62834-8d3a-4d3e-8987-1b7c97009bda.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('388-rabotniki-dalnevostochnogo-gazproma-otmetili-professionalnyj-prazdnik','Работники дальневосточного "Газпрома" отметили профессиональный праздник','2020-01-01','novosti','[]','Мероприятие прошло под эгидой профсоюзной организации компании. В нём приняло участие более 500 сотрудников и членов их семей. День работников нефтяной и газовой промышленности сотрудники «Газпром газораспределение Дальний Восток» из Хабаровска, Вяземского, Комсомольска-на-Амуре и Амурска отметили семейным фестивалем «ГазON». Он стал уже пятым по счету и прошел на туристической базе «Амур» в приго','/index.php/news/vse-novosti/388-rabotniki-dalnevostochnogo-gazproma-otmetili-professionalnyj-prazdnik','/images/news/gazprom.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('393-s-dnjom-rozhdeniya-fnpr','С Днём рождения, ФНПР!','2020-01-01','novosti','[]','19 сентября 1990 года было образовано крупнейшее профсоюзное объединение – Федерация Независимых Профсоюзов России. Вот уже 33 года эта организация, объединяя более 11 млн человек, последовательно выполняет главную миссию - защищает интересы человека труда, его право на безопасные условия труда, достойную заработную плату и обеспечение государственных социальных гарантий. ФНПР вносит существенный ','/index.php/news/vse-novosti/393-s-dnjom-rozhdeniya-fnpr','/images/news/ФНПР.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('402-s-prazdnikom-dorogie-uchitelya','С праздником, дорогие учителя!','2020-01-01','novosti','[]','Сегодня все школьники спешат на занятия с охапками цветов. всё это потому что на календаре 5 октября — профессиональный праздник тех, кто сеет разумное и вечное, День учителя! Сегодня прекрасный повод, чтобы поблагодарить тех, кто выбрал себе важную и сложную профессию. Многие люди только став взрослыми, понимают, каким важным был вклад преподавателей в их судьбу и карьеру. А пока это осознание не','/index.php/news/vse-novosti/402-s-prazdnikom-dorogie-uchitelya',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('413-s-yubileem-lyubimyj-kraj','С юбилеем, любимый край!','2020-01-01','novosti','[]','20 октября Хабаровскому краю исполняется 85 лет. Сегодня праздник для всех, кто искренне любит наш край, для кого много значит его историческое прошлое, кто верит в его будущее, гордится самобытной культурой и уникальной природной красотой региона, чтит земляков, оставивших след в его истории. Прошедшие 85 лет стали периодом становления и развития Хабаровского края как крупнейшего промышленного, э','/index.php/news/vse-novosti/413-s-yubileem-lyubimyj-kraj',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('415-zasedanie-ispolkoma-fnpr-okhrana-truda-i-itogi-vserossijskoj-aktsii-profsoyuzov','Заседание Исполкома ФНПР: охрана труда и итоги Всероссийской акции профсоюзов','2020-01-01','novosti','[]','31 октября на заседании Исполкома ФНПР участники обсудили охрану труда и здоровья работников, а также итоги Всероссийской акции профсоюзов в рамках Всемирного дня действий «За достойный труд!» Председатель ФНПР Михаил Шмаков рассказал о повестке, регламенте и составе рабочих органов предстоящего заседания Генсовета, на котором планируется рассмотреть вопросы о созыве XII съезда Федерации Независим','/index.php/news/vse-novosti/415-zasedanie-ispolkoma-fnpr-okhrana-truda-i-itogi-vserossijskoj-aktsii-profsoyuzov',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('416-gensovet-fnpr-prinyal-reshenie-o-sozyve-xii-s-ezda','Генсовет ФНПР принял решение о созыве XII Съезда','2020-01-01','novosti','[]','31 октября во Дворце труда профсоюзов состоялось заседание Генерального Совета Федерации Независимых Профсоюзов России, на котором обсудили созыв XII съезда Федерации и проведение отчетно-выборной кампании ФНПР в 2024-2026 годах. C соответствующими докладами выступил заместитель Председателя ФНПР Давид Кришталь. Генеральный Совет ФНПР принял решение созвать XII cъезд Федерации Независимых Профсоюз','/index.php/news/vse-novosti/416-gensovet-fnpr-prinyal-reshenie-o-sozyve-xii-s-ezda',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('417-torzhestvennoe-zasedanie-gensoveta-fnpr-ot-sovetskikh-profsoyuzov-k-sovremennym-profsoyuzam-rossii','Торжественное заседание Генсовета ФНПР – от советских профсоюзов к современным профсоюзам России','2023-11-01','novosti','[]','1 ноября в Колонном зале Дома союзов состоялось торжественное заседание Генерального Совета Федерации Независимых Профсоюзов России, основной темой которого стал исторический путь российских профсоюзов. В мероприятии приняли участие заместитель председателя правительства РФ Татьяна Голикова, первый заместитель председателя Госдумы Александр Жуков, статс-секретарь – заместитель министра труда Андре','/index.php/news/vse-novosti/417-torzhestvennoe-zasedanie-gensoveta-fnpr-ot-sovetskikh-profsoyuzov-k-sovremennym-profsoyuzam-rossii',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('423-vstrecha-prezidenta-rf-i-predsedatelya-fnpr','Встреча президента РФ и председателя ФНПР','2020-01-01','novosti','[]','Встреча Владимира Путина и Михаила Шмакова состоялась в минувшую среду, 3 мая. Профсоюзный лидер проинформировал главу государства о требованиях, выдвигавшихся в ходе первомайских мероприятий профсоюзов. Это, в первую очередь, - вопросы необходимости повышения заработной платы трудящимся. Не случайно главный лозунг Первомая - «Человеку труда - достойную зарплату». Кроме этого, «людей безусловно во','/index.php/news/vse-novosti/423-vstrecha-prezidenta-rf-i-predsedatelya-fnpr',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('424-kazhdomu-pogranichniku-khoroshuyu-knigu','Каждому пограничнику - хорошую книгу','2020-01-01','novosti','[]','Библиотеку из двух тысяч книг Хабаровское крайпрофобъединение передало в подарок воинам пограничной заставы «Чирки», что несут службу на российско-китайской границе по хребтам Хехцира и берегам рек Чирки и Уссури. Книги были собраны в преддверии Дня пограничника силами работников Хабаровского крайпрофобъединения. Инициативу отдела по вопросам детства, молодежи и международных связей, подхватили чл','/index.php/news/vse-novosti/424-kazhdomu-pogranichniku-khoroshuyu-knigu',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('426-v-kraevom-profsoyuze-rabotnikov-zhizneobespecheniya-proshlo-6-oe-zasedanie-plenuma','В краевом профсоюзе жизнеобеспечения прошло 6-е заседание пленума','2020-01-01','novosti','[]','В совещании приняли участие члены краевого комитета, ревизионной комиссии, а также председатели и профсоюзный актив первичных организаций. Перед началом заседания перед участниками мероприятия выступила заместитель директора Центра общественного здоровья и медицинской профилактики Татьяна Таранец с информацией о внедрении корпоративной программы по сохранению здоровья на предприятиях. Также были п','/index.php/news/vse-novosti/426-v-kraevom-profsoyuze-rabotnikov-zhizneobespecheniya-proshlo-6-oe-zasedanie-plenuma','/images/news/20231124_100526.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('427-dostojnyj-trud-i-profsoyuzy-vstrecha-finalistov-stratrezerv-2023-s-predsedatelem-fnpr','Достойный труд и профсоюзы. Встреча финалистов «Стратрезерв 2023» с председателем ФНПР','2020-01-01','novosti','[]','7 декабря Председатель Федерации независимых профсоюзов России Михаил Шмаков встретится с финалистами Всероссийской молодежной программы ФНПР «Стратегический резерв 2023». Там он назовет имя победителя первого Всероссийского конкурса «Молодой профсоюзный лидер России». Встреча состоится в рамках образовательной программы Международной выставки-форума «Россия», генеральным партнером которого являет','/index.php/news/vse-novosti/427-dostojnyj-trud-i-profsoyuzy-vstrecha-finalistov-stratrezerv-2023-s-predsedatelem-fnpr',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('430-profsoyuzy-i-kompaniya-kapital-life-podveli-itogi-goda-sotrudnichestva','Профсоюзы и компания «Капитал Life» подвели итоги года сотрудничества','2020-01-01','novosti','[]','В Хабаровске прошел бизнесс-завтрак «Новые возможности профсоюзов». В минувшую пятницу, 1 декабря, профсоюзный актив города встретился с нашими партнерами из страховой компании « Капитал Life ». Куратор проекта Анастасия Кириллова обсудила с участниками: Также были подведены итоги 2023 года. На сегодняшний день под защитой компании «Капитал Life» надодятся под более четырех тысяч членов профсоюзов','/index.php/news/vse-novosti/430-profsoyuzy-i-kompaniya-kapital-life-podveli-itogi-goda-sotrudnichestva','/images/news/whatsapp-image-2023-12-07-at-17_14_04.jpeg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('431-v-khabarovskom-krae-poyavilsya-novyj-profsoyuznyj-prazdnik','В Хабаровском крае появился новый профсоюзный праздник','2020-01-01','novosti','[]','В ходе торжественного собрания, посвященного 75-летию Хабаровского краевого объединения профсоюзов, в качестве главного подарка губернатор региона Михаил Дегтярев анонсировал решение установить 11 декабря памятную дату Хабаровского края — День образования профсоюзного движения. Напомним, что именно 11 декабря 1948 года было образовано Хабаровское профобъединение. Сегодня оно объединяет более 107 т','/index.php/news/vse-novosti/431-v-khabarovskom-krae-poyavilsya-novyj-profsoyuznyj-prazdnik','/images/news/rtv_3229.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('439-fnpr-initsiirovala-patrioticheskuyu-aktsiyu-v-zashchitu-mirnogo-naseleniya-i-obratilas-k-chlenam-profsoyuzov','ФНПР инициировала патриотическую акцию в защиту мирного населения и обратилась к членам профсоюзов','2020-01-01','novosti','[]','На Генеральном Совете ФНПР 17 января по инициативе ряда профсоюзных организаций было принято решение о проведении Патриотической акции «Профсоюзы России – Zа СВОих». ФНПР призывает членов профсоюзов перечислить однодневный заработок для приобретения и передачи Вооруженным Силам средств защиты населения от террористических атак. Средства будут перечисляться в Фонд «100 лет профсоюзного движения Рос','/index.php/news/vse-novosti/439-fnpr-initsiirovala-patrioticheskuyu-aktsiyu-v-zashchitu-mirnogo-naseleniya-i-obratilas-k-chlenam-profsoyuzov',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('441-vserossijskoe-soveshchanie-predsedatelej-pervichnykh-profsoyuznykh-organizatsij-sostoyalos-v-moskve','Всероссийское совещание председателей первичных профсоюзных организаций состоялось в Москве','2020-01-01','novosti','[]','Мероприятие прошло на площадке Международной выставки-форума «Россия» вчера, 5 февраля. В заседании приняли участие более 800 профлидеров со всей страны – председатели первичных профорганизаций, руководители отраслевых профсоюзов и территориальных профобъединений, руководство ФНПР. Работа совещания была построена на обсуждении важных для профсоюзов вопросов по четырем тематическим блокам: справедл','/index.php/news/vse-novosti/441-vserossijskoe-soveshchanie-predsedatelej-pervichnykh-profsoyuznykh-organizatsij-sostoyalos-v-moskve','/images/news/soveshchanie-fnpr.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('446-spasibo-vam-dorogie-zashchitniki','Спасибо вам, дорогие защитники!','2020-01-01','novosti','[]','Профсоюзы Хабаровского края поздравляют с Днём защитника Отечества всех причастных к этому празднику! Сегодня в нём воплощены чувства уважения наших граждан к доблестным защитникам, гордости за всех, кто служил и служит в армии и на флоте, признания их героических заслуг перед Родиной в отстаивании её суверенитета и независимости. Мы переживаем сложное время, период важнейших исторических событий,','/index.php/news/vse-novosti/446-spasibo-vam-dorogie-zashchitniki','/images/news/23.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('452-s-prazdnikom-rabotniki-bytovogo-obsluzhivaniya-i-zhkkh','С праздником, работники бытового обслуживания и ЖКХ!','2020-01-01','novosti','[]','Поздравление председателя Хабаровской краевой организации профсоюза работников жизнеобеспечения Натальи Плаксиной. От имени Хабаровской краевой организации профсоюза работников жизнеобеспечения и от себя лично поздравляю всех работников и ветеранов отрасли жизнеобеспечения с профессиональным праздником - Днем работников бытового обслуживания населения и жилищно-коммунального хозяйства! Жилищно-ком','/index.php/news/vse-novosti/452-s-prazdnikom-rabotniki-bytovogo-obsluzhivaniya-i-zhkkh',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('457-cheloveku-truda-slava','Человеку труда - слава!','2020-01-01','novosti','[]','Замечательное мероприятие прошло 1 мая на Площади Победы Николаевска-на-Амуре. Здесь собралось больше 500 человек. Концерт, викторина с розыгрышем призов, демонстрация мастерства юных велосипедистов, выставка робототехники и многое другое. В своём выступлении заместитель главы администрации Николаевского муниципального района по социальным вопросам Светлана Ерёмина подчеркнула важность первомайско','/index.php/news/vse-novosti/457-cheloveku-truda-slava',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('466-v-ryadakh-profsoyuza-rabotnikov-gosuchrezhdenij-popolnenie','В рядах профсоюза работников госучреждений пополнение','2020-01-01','novosti','[]','Первичная профсоюзная организация создана в Управлении Федеральной службы судебных приставов по Хабаровскому краю. Такое решение приняли работники на общем собрании организации , прошедшего 19 апреля. Председателем профорганизации стал исполняющий обязанности заместителя руководителя Управления Максим Дубс . Также были избраны профсоюзный комитет и ревизионная комиссия, в состав которых вошли сотр','/index.php/news/vse-novosti/466-v-ryadakh-profsoyuza-rabotnikov-gosuchrezhdenij-popolnenie',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('467-v-sostav-kraevogo-profob-edineniya-voshla-novaya-organizatsiya','В состав краевого профобъединения вошла новая организация','2020-01-01','novosti','[]','Территориальная организация профсоюза гражданского персонала Вооружённых Сил России Восточного военного округа вошла в состав Хабаровского краевого объединения организаций профсоюзов. Такое решение единогласно было принято на очередном заседании Совета профобъединения 20 апреля. Организация профсоюза гражданского персонала Вооружённых Сил России ВВО существует более 26 лет и была создана 7 сентябр','/index.php/news/vse-novosti/467-v-sostav-kraevogo-profob-edineniya-voshla-novaya-organizatsiya',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('468-55-let-na-zashchite-prav-trudyashchikhsya','55 лет на защите прав трудящихся','2020-01-01','podderzhka','[]','Энергетики Хабаровского края и Еврейской автономной области отметили юбилей межрегиональной организации Всероссийского Электропрофсоюза. На торжественное мероприятие, посвященное юбилею организации, собрались профсоюзные активисты, ветераны и работники отрасли, социальные партнеры – руководители предприятий энергетики Хабаровского края и Еврейской автономной области и представители Хабаровского кр','/index.php/news/vse-novosti/468-55-let-na-zashchite-prav-trudyashchikhsya',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('470-komsomolskie-aviastroiteli-otmetili-den-aviatsii-i-kosmonavtiki','Комсомольские авиастроители отметили День авиации и космонавтики','2020-01-01','novosti','[]','В торжественном митинге, посвященном 56-й годовщине первого полета человека в космос и 40-летию присвоения Комсомольскому-на-Амуре авиационному заводу имени Юрия Гагарина, приняли участие около пятисот работников филиала ПАО «Компания « Сухой » « КнААЗ им. Ю.А. Гагарина ». Также на торжественном мероприятии присутствовали курсанты Клуба юных моряков, учащиеся школ Ленинского округа, ветераны. В эт','/index.php/news/vse-novosti/470-komsomolskie-aviastroiteli-otmetili-den-aviatsii-i-kosmonavtiki',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('471-profsoyuzy-rossii-protiv-peredachi-rosstata-ministerstvu-ekonomiki','Профсоюзы России против передачи Росстата Министерству экономики','2020-01-01','novosti','[]','Профсоюзы выступают категорически против того, чтобы Росстат перешел в ведение Минэкономразвития. Об этом 11 апреля на заседании Российской трехсторонней комиссии по социально-трудовым отношениям заявил председатель Федерации независимых профсоюзов России Михаил Шмаков. - Профсоюзная сторона РТК неоднократно обращала внимание Комиссии на попытки Минфина России и Минэкономразвития России манипулиро','/index.php/news/vse-novosti/471-profsoyuzy-rossii-protiv-peredachi-rosstata-ministerstvu-ekonomiki',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('472-optimizatsiya-v-zdravookhranenii-ne-privela-k-rostu-zarplat-medrabotnikov','Оптимизация в здравоохранении не привела к росту зарплат медработников','2020-01-01','novosti','[]','Одним из центральных процессов в российском здравоохранении в последние годы стала «оптимизация». Эксперты Центра экономических и политических реформ (ЦЭПР) подготовили доклад « ЗдравоЗахоронение. Оптимизация российской системы здравоохранения в действии ». Согласно официальным данным Росстата, число больничных организаций в России с 2000 по 2015 год сократилось в два раза – с 10,7 до 5,4 тысяч ор','/index.php/news/vse-novosti/472-optimizatsiya-v-zdravookhranenii-ne-privela-k-rostu-zarplat-medrabotnikov',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('473-profsoyuzy-prizvali-pravitelstvo-ne-szhimat-pruzhinu-russkogo-terpeniya','Профсоюзы призвали правительство «не сжимать пружину русского терпения»','2020-01-01','podderzhka','[]','Сравнить события начала и конца прошлого века с сегодняшним днем – с таким предложением к участникам генерального совета Федерации независимых профсоюзов России выступил руководитель профцентра Михаил Шмаков. По мнению профсоюзного лидера, как тогда, так и сейчас Россия испытывает внешнеполитическое давление, и фактически идет не объявленная «гибридная» война. Кроме того, ситуацию в стране портят ','/index.php/news/vse-novosti/473-profsoyuzy-prizvali-pravitelstvo-ne-szhimat-pruzhinu-russkogo-terpeniya',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('474-golodets-profsoyuzy-pomogayut-kontrolirovat-ispolnenie-majskikh-ukazov','Голодец: профсоюзы помогают контролировать исполнение «майских указов»','2020-01-01','novosti','[]','За прошлый год благодаря инициативам профсоюзов и самих работников удалось добиться возвращения порядка 25 млрд рублей недоплаченной зарплаты. Об этом 4 апреля, выступая на генеральном совете ФНПР, заявила вице-премьер российского правительства Ольга Голодец. По ее словам, благодаря действиям социальных партнеров и реакции трудинспекции, вернуть заработанные деньги удалось более чем миллиону челов','/index.php/news/vse-novosti/474-golodets-profsoyuzy-pomogayut-kontrolirovat-ispolnenie-majskikh-ukazov',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('476-profsoyuzy-rossii-potrebovali-ukrepit-finansovo-ekonomicheskij-blok-pravitelstva','Профсоюзы России потребовали укрепить финансово-экономический блок правительства','2020-01-01','podderzhka','[]','Вместо того чтобы учить российских рабочих патриотизму с высоких трибун, им нужно обеспечить достойный уровень жизни. Об этом председатель Федерации независимых профсоюзов России Михаил Шмаков заявил, выступая на генеральном совете крупнейшего профцентра страны 4 апреля. Как подчеркнул профсоюзный лидер, для этого необходимо выполнить три условия: укрепить финансово-экономический блок правительств','/index.php/news/vse-novosti/476-profsoyuzy-rossii-potrebovali-ukrepit-finansovo-ekonomicheskij-blok-pravitelstva',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('477-rabotniki-zavoda-vympel-zayavili-o-sebe-na-viii-profolimpijskikh-igrakh','Работники завода «Вымпел» заявили о себе на VIII Профолимпийских играх','2020-01-01','novosti','[]','Работники завода « Вымпел » заявили о себе на VIII Профолимпийских играх. По итогам соревнований в копилке спортивных побед предприятия – «золото» в личном первенстве по дартсу и по метанию колец в командном первенстве. Профолимпийские игры - это ежегодный спортивный праздник в Комсомольске-на-Амуре, организуемый Хабаровским краевым профобъединением и Координационным советом организаций профсоюзов','/index.php/news/vse-novosti/477-rabotniki-zavoda-vympel-zayavili-o-sebe-na-viii-profolimpijskikh-igrakh',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('478-khabarovchane-stali-laureatami-premii-obshcherossijskogo-profsoyuza-rabotnikov-zhizneobespecheniya-po-itogam-2016-go','Хабаровчане стали лауреатами премии Общероссийского профсоюза работников жизнеобеспечения по итогам 2016 года','2020-01-01','novosti','[]','Это ежегодная премия, присуждаемая рабочим, мастерам, инженерно-техническим работникам и специалистам отраслей, объединяемых профсоюзом, добившимся высоких результатов в труде и техническом творчестве, работающим на протяжении длительного времени без травм и аварий, активно участвующим в деятельности отраслевого профсоюза. По итогам 2016 года лучшими по Хабаровскому краю стали слесарь по обслужива','/index.php/news/vse-novosti/478-khabarovchane-stali-laureatami-premii-obshcherossijskogo-profsoyuza-rabotnikov-zhizneobespecheniya-po-itogam-2016-goda',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('479-profsoyuzu-aviarabotnikov-dalnego-vostoka-80-let','Профсоюзу авиаработников Дальнего Востока – 80 лет','2020-01-01','novosti','[]','Авиаторы Дальнего Востока отметили юбилей территориальной организации профсоюза авиационных работников. На торжественное собрание, прошедшее на площадке краевого профобъединения 29 марта, собрались профсоюзные работники, активисты и ветераны профдвижения отрасли Хабаровского края, Амурской и Сахалинской области, Приморья и Камчатки. Также в мероприятии приняли участие социальные партнеры – руковод','/index.php/news/vse-novosti/479-profsoyuzu-aviarabotnikov-dalnego-vostoka-80-let',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('480-nagrazhdeny-luchshie-profsoyuznye-organizatsii-uchrezhdenij-zdravookhraneniya-kraya','Награждены лучшие профсоюзные организации учреждений здравоохранения края','2020-01-01','novosti','[]','Хабаровская краевая организация подвела итоги смотра-конкурса « Лучшая первичная организация профсоюза в 2016 году ». Дипломы и денежные премии профсоюзным лидерам вручила председатель краевой организации Ольга Адмидина на расширенном заседании президиума 24 марта. Первое место в смотре-конкурсе заняли: среди организаций с численностью до 150 членов профсоюза - профсоюзная организация КГБУЗ «Детск','/index.php/news/vse-novosti/480-nagrazhdeny-luchshie-profsoyuznye-organizatsii-uchrezhdenij-zdravookhraneniya-kraya',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('486-sovetu-veteranov-nizhneamurya-30-let','Совету ветеранов Нижнеамурья - 30 лет','2020-01-01','novosti','[]','Праздничным собранием в Николаевске-на-Амуре отметили юбилей районной организации ветеранов. С 30-летием совет пришли поздравить и представители профсоюзов. Торжество по случаю юбилея было организовано в районном Доме культуры. В этот праздничный день в адрес ветеранов звучало много теплых слов благодарности за трудовые и боевые заслуги перед Отечеством и деятельность в мирное время. Активистам ве','/index.php/news/vse-novosti/486-sovetu-veteranov-nizhneamurya-30-let',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('491-svyshe-trekh-desyatkov-knig-sobrali-dlya-selskikh-bibliotek-aktivisty-kraevogo-profsoyuza-rabotnikov-gosuchrezhdenij','Свыше трех десятков книг собрали для сельских библиотек активисты краевого профсоюза работников госучреждений','2020-01-01','novosti','[]','Краевая организация профсоюза работников госучреждений и общественного обслуживания присоединилась к благотворительной акции #АгроМания по сбору книг в пользу сельских библиотек. Акцию поддержали профсоюзные активисты и работники аппарата краевого комитета организации профсоюза, Дальневосточного банка ОАО " Сбербанк России ", УМВД России по Хабаровскому краю, Хабаровского Дома-интерната для преста','/index.php/news/vse-novosti/491-svyshe-trekh-desyatkov-knig-sobrali-dlya-selskikh-bibliotek-aktivisty-kraevogo-profsoyuza-rabotnikov-gosuchrezhdenij',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('492-rabotayushchikh-khabarovchan-priglashayut-sdat-normy-gto','Работающих хабаровчан приглашают сдать нормы ГТО','2020-01-01','novosti','[]','Первый фестиваль для работников предприятий и организаций Хабаровска пройдет в краевой столице 25 марта, - сообщают в пресс-службе городской администрации. - Это первый фестиваль для работающего населения. Если раньше нормы комплекса « Готов к труду и обороне » сдавали школьники, то сейчас это может сделать любой желающий, так как в 2017 году начался основной этап сдачи нормативов, - отметил главн','/index.php/news/vse-novosti/492-rabotayushchikh-khabarovchan-priglashayut-sdat-normy-gto',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('496-s-1-fevralya-strakhovye-pensii-i-sotsialnye-vyplaty-rossiyan-uvelichivayutsya-na-5-4','С 1 февраля страховые пенсии и социальные выплаты россиян увеличиваются на 5,4%','2020-01-01','novosti','[]','С 1 февраля страховые пенсии неработающих пенсионеров и ежемесячные денежные выплаты федеральных льготников будут выплачиваться в увеличенном размере. Это произойдет в результате индексации на 5,4% исходя из роста потребительских цен за 2016 год, - сообщает пресс-служба отделения ПФР по Хабаровскому краю . Вместе со страховой пенсией индексируется на 5,4% фиксированная выплата. Теперь она составля','/index.php/news/vse-novosti/496-s-1-fevralya-strakhovye-pensii-i-sotsialnye-vyplaty-rossiyan-uvelichivayutsya-na-5-4',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('498-razmer-posobij-pri-rozhdenii-rebenka-i-ukhodu-za-nim-uvelichen-v-khabarovskom-krae','Размер пособий при рождении ребенка и уходу за ним увеличен в Хабаровском крае','2020-01-01','novosti','[]','С февраля в Российской Федерации увеличился размер пособий при рождении ребенка и последующего ухода за ним. Все выплаты из этой категории проиндексированы на 5,4%, - сообщает пресс-служба губернатора и правительства Хабаровского края. Так, размер единовременного пособия, выплачиваемого при рождении, теперь составляет 16,3 тысячи рублей (ранее примерно 15,5 тыс. рублей). Размер ежемесячного пособи','/index.php/news/vse-novosti/498-razmer-posobij-pri-rozhdenii-rebenka-i-ukhodu-za-nim-uvelichen-v-khabarovskom-krae',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('502-nam-vsem-ne-stoit-zabyvat-uroki-1917-go','Нам всем не стоит забывать уроки 1917-го','2020-01-01','novosti','[]','Наступивший 2017 год, по мнению главы Федерации независимых профсоюзов России Михаила Шмакова, знаковый. Сто лет назад нашу страну потрясли две революции, в ходе которых рухнули несущие конструкции государства. Казалось, те уроки истории Россия давно усвоила и подобные потрясения не должны повториться. Однако многие из роковых обстоятельств, что век назад привели страну к неслыханным катаклизмам, ','/index.php/news/vse-novosti/502-nam-vsem-ne-stoit-zabyvat-uroki-1917-go',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('504-pensionnaya-sistema-chto-zhdet-zhitelej-khabarovskogo-kraya-v-2017-godu','Пенсионная система: что ждет жителей Хабаровского края в 2017 году','2020-01-01','novosti','[]','В пенсионной системе России в 2017 году произойдет ряд событий и изменений, которые коснутся всех участников системы обязательного пенсионного страхования: и нынешних, и будущих пенсионеров, а также работодателей. Повышение пенсий и социальных выплат В 2017 году индексация пенсий вернется к прежнему порядку, когда страховые пенсии увеличиваются на уровень фактической инфляции, а госпенсии, включая','/index.php/news/vse-novosti/504-pensionnaya-sistema-chto-zhdet-zhitelej-khabarovskogo-kraya-v-2017-godu',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('505-edinovremennaya-vyplata-pensioneram-aktualnye-voprosy','Единовременная выплата пенсионерам: актуальные вопросы','2020-01-01','novosti','[]','Пенсионеры Хабаровского края начали получать единовременную выплату в размере 5 тыс. рублей. Её доставка в январе продолжится по 28 число. В связи с этим на «горячую линию» Отделения ПФР по Хабаровскому краю поступают звонки от граждан, которые хотят получить более подробную информацию о выплате. На самые распространённые вопросы ответила начальник управления организации назначения и выплаты пенси','/index.php/news/vse-novosti/505-edinovremennaya-vyplata-pensioneram-aktualnye-voprosy',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('511-profsoyuznye-pobedy-2016-goda','Профсоюзные победы 2016 года','2020-01-01','novosti','[]','В конце года газета "Солидарность" решила вспомнить наиболее важные победы профсоюзного движения. Да, профсоюзы многих защитили на предприятиях, в судах, были достижения и в рамках целых регионов. Но сейчас мы сделали подборку побед именно в масштабах всей страны. Всего этого не было бы, если бы не активные действия Федерации независимых профсоюзов России. 1. Председатель ФНПР Михаил Шмаков на вст','/index.php/news/vse-novosti/511-profsoyuznye-pobedy-2016-goda',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('514-predpriyatiyu-voskhod-75-let','Предприятию «Восход» - 75 лет!','2020-01-01','novosti','[]','Сегодня свой 75-летний юбилей торжественно отметит Дальневосточное производственное объединение «Восход». Это крупнейшее предприятие - единственное на территории всего Дальнего Востока, которое выпускает промышленные взрывчатые вещества. С юбилеем руководство и коллектив предприятия поздравляет председатель Хабаровского профобъединения Галина Кононенко. - Немногие предприятия региона имеют такую б','/index.php/news/vse-novosti/514-predpriyatiyu-voskhod-75-let',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('520-kurs-na-ukreplenie-i-razvitie-profsoyuza','Курс – на укрепление и развитие профсоюза','2020-01-01','novosti','[]','IV Пленум Хабаровской краевой организации профсоюза работников здравоохранения поставил приоритетные задачи на ближайший период и принял Программу организационного и финансового укрепления организации на 2017-2019 годы. - Сегодня нам предстоит серьезный и откровенный разговор о перспективах деятельности нашей организации, - открыла заседание председатель Хабаровской краевой организации профсоюза р','/index.php/news/vse-novosti/520-kurs-na-ukreplenie-i-razvitie-profsoyuza',NULL);
