INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('530-mrot-sdelali-gryaznym','МРОТ сделали грязным','2016-08-08','novosti','[]','Осенью Верховный суд принял два определения, согласно которым в “минималку” можно включать все виды надбавок. И в некоторые суды уже поступила рекомендация руководствоваться логикой ВС при рассмотрении соответствующих исков: в каких бы суровых условиях ты ни работал, зарплату все равно могут ограничить “минималкой”. В регионах уже готовятся к акциям протеста, - сообщает газета "Солидарность" . Про','/index.php/news/vse-novosti/530-mrot-sdelali-gryaznym',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('533-gensovet-fnpr-opredelil-zadachi-profsoyuzov-v-tekushchikh-sotsialno-ekonomicheskikh-usloviyakh','Генсовет ФНПР определил задачи профсоюзов в текущих социально-экономических условиях','2020-01-01','novosti','[]','Заседание Генерального Совета Федерации независимых профсоюзов России прошло 26 октября в Москве. В нем приняли участие представители территориальных и отраслевых организаций профсоюзов, объединений работодателей, депутаты Госдумы РФ. Хабаровский край на Генсовете представила председатель краевого профобъединения Галина Кононенко. В числе главных вопросов участники заседания обсудили задачи профсо','/index.php/news/vse-novosti/533-gensovet-fnpr-opredelil-zadachi-profsoyuzov-v-tekushchikh-sotsialno-ekonomicheskikh-usloviyakh',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('534-proflidery-zdravookhraneniya-dalnego-vostoka-obsudili-problemy-medrabotnikov','Профлидеры здравоохранения Дальнего Востока обсудили проблемы медработников','2020-01-01','novosti','[]','Окружная конференция руководителей территориальных организаций профсоюза работников здравоохранения Дальневосточного федерального округа прошла в Южно-Сахалинске с 12 по 13 сентября. Участие в ней приняли председатели региональных организаций профсоюза здравоохранения Амурской, Магаданской и Московской областей, Республики Саха (Якутия), Камчатского, Приморского и Хабаровского краев. Также на меро','/index.php/news/vse-novosti/534-proflidery-zdravookhraneniya-dalnego-vostoka-obsudili-problemy-medrabotnikov',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('537-shest-voprosov-povtoryaemykh-zhurnalistami-iz-goda-v-god','Шесть вопросов, повторяемых журналистами из года в год','2020-01-01','novosti','[]','Из года в год журналисты звонят в профорганизации и задают одни и те же вопросы. Газета "Солидарность" сделала подборку вопросов и ответов, чтобы в следующий раз, когда внезапно настанет лето или Первомай, журналистам не нужно было заново искать информацию. Чем работодатель обязан обеспечить сотрудников во время жары? Права работников во время жаркой погоды регулирует СанПиН 2.2.4.54896 «Гигиениче','/index.php/news/vse-novosti/537-shest-voprosov-povtoryaemykh-zhurnalistami-iz-goda-v-god',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('539-territorialnoe-ob-edinenie-rabotodatelej-v-sfere-zhkkh-poyavitsya-v-khabarovskom-krae','Территориальное объединение работодателей в сфере ЖКХ появится в Хабаровском крае','2020-01-01','novosti','[]','Территориальное объединение работодателей в сфере ЖКХ появится в Хабаровском крае. Возможность его создания обсудили на заседании круглого стола « Новое в модернизации ЖКХ: О приоритетной роли объединения работодателей и профсоюза жизнеобеспечения », прошедшем в Хабаровске 9 августа. К участию в актуальном разговоре были приглашены генеральный директор Центра по сертификации в жилищно-коммунальном','/index.php/news/vse-novosti/539-territorialnoe-ob-edinenie-rabotodatelej-v-sfere-zhkkh-poyavitsya-v-khabarovskom-krae',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('542-novyj-razmer-prozhitochnogo-minimuma-utverzhdjon-v-khabarovskom-krae','Новый размер прожиточного минимума утверждён в Хабаровском крае','2020-01-01','novosti','[]','Новый размер прожиточного минимума на II квартал 2016 года установлен в Хабаровском крае. Соответствующее постановление подписал губернатор Вячеслав Шпорт. Величина прожиточного минимума на душу населения, по сравнению с I кварталом, в среднем увеличилась на 1,2 %, составив 13 174 рубля. Повышение произошло за счёт изменения стоимости продуктового набора, которая, по данным Хабаровскстата, подросл','/index.php/news/vse-novosti/542-novyj-razmer-prozhitochnogo-minimuma-utverzhdjon-v-khabarovskom-krae',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('544-profsoyuzy-namereny-suditsya-s-kandidatom-v-deputaty-gosdumy-delyaginym','Профсоюзы намерены судиться с кандидатом в депутаты Госдумы Делягиным','2020-01-01','novosti','[]','Обострение политического процесса, связанное с выборами, накладывает отпечаток на некоторые нестойкие умы. Кандидат в депутаты Госдумы от партии " Справедливая Россия " Михаил Делягин, судя по публикациям на личном сайте, являющийся корифеем множества наук и директором Института проблем глобализации с крайне немногочисленным штатом, высказался о трудовых отношениях. Из его слов следовало, что Труд','/index.php/news/vse-novosti/544-profsoyuzy-namereny-suditsya-s-kandidatom-v-deputaty-gosdumy-delyaginym',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('553-zayavlenie-federatsii-nezavisimykh-profsoyuzov-rossii-2','Заявление Федерации Независимых Профсоюзов России','2020-01-01','novosti','[]','Вечером 22 марта террористы использовали концерт в Крокус-сити с большим количеством зрителей для жестокого и обдуманного убийства. ФНПР выражает сочувствие жертвам террористического акта, их родным и близким. Мы готовы оказать любую необходимую помощь. Не сомневаемся, что правоохранители найдут и справедливо покарают не только террористов, но и организаторов, и идеологов этого бесчеловечного прес','/index.php/news/vse-novosti/553-zayavlenie-federatsii-nezavisimykh-profsoyuzov-rossii-2',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('554-obrashchenie-proflidera-khabarovskogo-kraya-galiny-kononenko','Обращение профлидера Хабаровского края Галины Кононенко','2020-01-01','novosti','[]','Сегодня в России общенациональный траур. Сложно подобрать слова, выражающие ту боль и сострадание, негодование и желание возмездия, которые испытывают россияне вследствие бесчеловечной террористической акции в «Крокус Сити Холле». Мирные люди стали жертвами бесчувственных тварей, пролилась кровь невинных детей. Такое прощать нельзя! Справедливое возмездие неминуемо! Беда на Руси всегда объединяла ','/index.php/news/vse-novosti/554-obrashchenie-proflidera-khabarovskogo-kraya-galiny-kononenko',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('558-voprosy-zashchity-prav-rabotnikov-i-predprinimatelej-obsudili-predstaviteli-prokuratury-profsoyuzov-i-biznes-soobshc','Вопросы защиты прав работников и предпринимателей обсудили представители прокуратуры, профсоюзов и бизнес-сообществ','2020-01-01','podderzhka','[]','Первый открытый форум прокуратуры Хабаровского края, посвященный вопросам соблюдения трудовых прав граждан и устранения административных барьеров в бизнесе, прошел 29 июня в Хабаровске . Актуальная тема объединила представителей краевой прокуратуры, профсоюзов, Общественной палаты, Совета по предпринимательству и улучшению инвестиционного климата Хабаровского края, объединения промышленников и пре','/index.php/news/vse-novosti/558-voprosy-zashchity-prav-rabotnikov-i-predprinimatelej-obsudili-predstaviteli-prokuratury-profsoyuzov-i-biznes-soobshchestv',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('561-trudovoe-zakonodatelstvo-rossii-sistematizirovali-v-internete','Трудовое законодательство России систематизировали в интернете','2020-01-01','novosti','[]','5 июля на заседании Общественного совета при Роструде состоялась презентация нового сервиса " Перечень требований трудового законодательства " портала " Онлайнинспекция.рф ". Особого упоминания требует большая работа по систематизации законодательства по охране труда, проведенная на портале. - У нас всего существует 667 актов по охране труда, и ни один работодатель просто не в силах знать их все, ','/index.php/news/vse-novosti/561-trudovoe-zakonodatelstvo-rossii-sistematizirovali-v-internete',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('562-novym-rabochim-professiyam-obuchat-v-regione','Новым рабочим профессиям обучат в регионе','2020-01-01','novosti','[]','Меры по совершенствованию региональной системы среднего профобразования обсудили сегодня на заседании коллегии минобрнауки Хабаровского края. В мероприятии приняли участие представители профильных ведомств, образовательных учреждений. Как отметила министр образования и науки края Алла Кузнецова, одной из ключевых задач сегодня является подготовка квалифицированных кадров для развития ТОСЭР «Хабаро','/index.php/news/vse-novosti/562-novym-rabochim-professiyam-obuchat-v-regione',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('571-za-vernost-professii','За верность профессии','2020-01-01','novosti','[]','Накануне Дня медицинского работника в министерстве здравоохранения края подвели итоги ежегодного краевого конкурса «Признание». Победителями и призерами в различных номинациях признаны свыше 50 специалистов из Охотского, Николаевского, Бикинского, Амурского, Комсомольского, Нанайского, Хабаровского районов и района им. Лазо, Хабаровска и Комсомольска-на-Амуре - 37 врачей, три провизора, 17 средних','/index.php/news/vse-novosti/571-za-vernost-professii',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('582-nachalsya-xii-s-ezd-fnp','Начался XII съезд ФНПР','2020-01-01','novosti','[]','Мероприятия в рамках Съезда продлятся в Москве до 5 апреля. На них планируется обсудить и принять Программу ФНПР «За справедливую экономику!», резолюции по направлениям работы профсоюзов, внести изменения в Устав Федерации и избрать Председателя ФНПР. На Съезд прибыли более 600 делегатов, избранных членскими организациями ФНПР: руководители профсоюзов и профсоюзных объединений, представители орган','/index.php/news/vse-novosti/582-nachalsya-xii-s-ezd-fnp','/images/news/img_5847.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('583-rezolyutsii-xii-s-ezda-fnpr','Резолюции XII съезда ФНПР','2020-01-01','novosti','[]','XII съезд принял резолюции, посвященные основным направлениям деятельности профсоюзов. В документах предлагаются важные акценты в части оценок проблем и работы профсоюзов на перспективу. Резолюции представили заместители Председателя ФНПР, руководители общероссийских, межрегиональных профсоюзов, территориальных объединений организаций профсоюзов и члены Молодежного Совета ФНПР. Каждому работнику –','/index.php/news/vse-novosti/583-rezolyutsii-xii-s-ezda-fnpr',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('584-prezident-rossii-vystupil-na-xii-s-ezde-fnpr','Президент России выступил на XII съезде ФНПР','2020-01-01','novosti','[]','4 апреля XII съезд Федерации независимых профсоюзов России продолжил свою работу в Москве. На заседании выступил Президент РФ Владимир Путин . По словам главы государства, ФНПР входит в число ведущих институтов гражданского общества, выполняет ответственную миссию, защищает трудовые права сотрудников компаний, предприятий, коллективов целых отраслей производства, тех, кто работает в сфере образова','/index.php/news/vse-novosti/584-prezident-rossii-vystupil-na-xii-s-ezde-fnpr',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('585-xii-s-ezd-prinyal-programmu-fnpr-za-spravedlivuyu-ekonomiku','XII съезд принял Программу ФНПР «За справедливую экономику!»','2020-01-01','podderzhka','[]','С докладом по проекту Программы выступила заместитель Председателя ФНПР Нина Кузьмина. Посмотреть запись выступления можно здесь. Программа ФНПР отражает позицию российских профсоюзов о том, что: ● справедливая экономика – это, прежде всего, экономика высоких заработных плат, ● в справедливой экономике все трудящиеся должны иметь равные права и гарантии в сфере труда независимо от формы занятости,','/index.php/news/vse-novosti/585-xii-s-ezd-prinyal-programmu-fnpr-za-spravedlivuyu-ekonomiku',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('586-zavershilsya-xii-s-ezd-fnpr','Завершился XII съезд ФНПР','2020-01-01','novosti','[]','Основным вопросом финального дня съезда стало внесение изменений в Устав Федерации независимых профсоюзов России. С докладом по вопросу выступил заместитель Председателя ФНПР Сергей Некрасов . Делегаты приняли соответствующее постановление. В завершении съезда Председатель ФНПР поблагодарил делегатов и гостей за активную и плодотворную работу, в том числе за совместное принятие важных и актуальных','/index.php/news/vse-novosti/586-zavershilsya-xii-s-ezd-fnpr',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('587-vserossijskaya-yarmarka-trudoustrojstva-projdet-v-khabarovskom-krae','Всероссийская ярмарка трудоустройства пройдет в Хабаровском крае','2020-01-01','novosti','[]','Уже в эту пятницу, 12 апреля, свои двери откроет Всероссийская ярмарка трудоустройства. Если Вы ищите работу или хотите сменить вид деятельности – это мероприятие для Вас! Более 100 организаций, среди которых Комсомольский-на-Амуре авиационный завод имени Ю.А. Гагарина, Амурский судостроительный завод, Дальневосточная генерирующая компания, Амурский гидродметаллургический комбинат, Хабаровский аэр','/index.php/news/vse-novosti/587-vserossijskaya-yarmarka-trudoustrojstva-projdet-v-khabarovskom-krae',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('593-pionery-trudovoj-mobilnosti-pribyvayut-v-kraj','Пионеры «трудовой мобильности» прибывают в край','2020-01-01','novosti','[]','В 2015 году по программе повышения трудовой мобильности Хабаровский край принял 54 работника из иных субъектов Российской Федерации, наиболее востребованных предприятиями края. Таким образом, положено начало реализации большого государственного дела - обеспечения квалифицированными кадрами Дальнего Востока. Конечно, работников из иных регионов страны наши предприятия привлекали и раньше. Немало та','/index.php/news/vse-novosti/593-pionery-trudovoj-mobilnosti-pribyvayut-v-kraj',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('594-ix-s-ezd-federatsii-nezavisimykh-profsoyuzov-rossii-otkrylsya-v-sochi','IX Съезд Федерации независимых профсоюзов России открылся в Сочи','2020-01-01','novosti','[]','На главный профсоюзный форум собралось свыше 700 делегатов со всех регионов страны, представляющих интересы более чем 21 миллиона членов профсоюзов. Участие в форуме принимает Президент РФ Владимир Путин и руководители других ветвей государственной власти, члены Правительства и Федерального Собрания РФ, представители объединений работодателей, руководители международных профсоюзных объединений и п','/index.php/news/vse-novosti/594-ix-s-ezd-federatsii-nezavisimykh-profsoyuzov-rossii-otkrylsya-v-sochi',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('596-ix-s-ezd-fnpr-prodolzhaet-rabotu','IX съезд ФНПР продолжает работу','2020-01-01','novosti','[]','В Сочи завершился уже второй день главного профсоюзного форума - IX съезда Федерации независимых профсоюзов России. Делегаты обсудили основные направления работы профсоюзов, определили задачи и планы на будущее, приняли ряд важных резолюций и избрали председателя Федерации. Напомним, съезд ФНПР начался 7 февраля. Участие в нем принимает делегация Хабаровского края , возглавляемая председателем кра','/index.php/news/vse-novosti/596-ix-s-ezd-fnpr-prodolzhaet-rabotu',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('597-dostojnyj-trud-osnova-blagosostoyaniya-cheloveka-i-razvitiya-strany','Достойный труд - основа благосостояния человека и развития страны','2020-01-01','novosti','[]','IX съезд Федерации независимых профсоюзов России завершился в Сочи. На итоговом заседании 9 февраля были избраны Генеральный Совет, Исполнительный комитет и Контрольно-ревизионную комиссию ФНПР. Делегаты съезда обсудили и приняли Программу ФНПР «Достойный труд – основа благосостояния человека и развития страны», направленную на преодоление дефицита достойного труда. Этот посыл признан делегатами п','/index.php/news/vse-novosti/597-dostojnyj-trud-osnova-blagosostoyaniya-cheloveka-i-razvitiya-strany',NULL);
