INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('604-pomogi-uvelichit-mrot-projdi-opros','Помоги увеличить МРОТ - пройди опрос!','2020-01-01','novosti','[]','ФНПР разработала собственную методику исчисления величины минимального потребительского восстановительного бюджета, которая, по мнению профсоюзов, должна стать ориентиром для установления минимального размера оплаты труда. В целях совершенствования данной методики ФНПР в 2024 году проводит анонимный опрос среди членов профсоюзов на предмет значимости приобретения непродовольственных товаров и услу','/index.php/news/vse-novosti/604-pomogi-uvelichit-mrot-projdi-opros',NULL);
