INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('674-zayavlenie-generalnogo-soveta-federatsii-nezavisimykh-profsoyuzov-rossii','Заявление Генерального Совета Федерации Независимых Профсоюзов России','2020-01-01','novosti','[]','В связи с проводимой против российских профсоюзов кампанией по попыткам изъятия профсоюзного имущества в пользу государства, Генеральный Совет ФНПР – постоянно действующий руководящий орган Федерации – заявляет: 1. Российские профсоюзы, являясь самофинансируемыми некоммерческими организациями, выполняют свои уставные обязанности по организации и защите трудовых прав работников – членов профсоюзов,','/index.php/news/vse-novosti/674-zayavlenie-generalnogo-soveta-federatsii-nezavisimykh-profsoyuzov-rossii',NULL);
