INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('686-skoro-pryamoj-efir-s-aleksandrom-shershukovym','СКОРО прямой эфир с Александром Шершуковым','2020-01-01','novosti','[]','Уже в этот четверг, 22 августа, в 12:00 на канале «Солидарности» в Rutube состоится прямой эфир «Профсоюзный подход с Александром Шершуковым». Заместитель председателя ФНПР и главный редактор газеты «Солидарность» Александр Шершуков расскажет о горячих новостях профсоюзов (накануне пройдет заседание исполнительного комитета ФНПР) и поделится экспертным мнением о самых острых вопросах, которые стоя','/index.php/news/vse-novosti/686-skoro-pryamoj-efir-s-aleksandrom-shershukovym','/images/news/adf09c9fb9def95c51f00c730649bdfb.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('688-knaazu-90-let','КнААЗу – 90 лет!','2020-01-01','novosti','[]','Комсомольский-на-Амуре авиационный завод имени Гагарина в этом году отметил свой 90-летний юбилей. Традиционно день рождения завода приурочивают к празднованию Дня Воздушного Флота России – профессионального праздника гагаринцев, поэтому этот день широко отмечается и городом, и заводом. --> --> --> Смотреть встроенную онлайн галерею в: https://habprof.ru/index.php/news/vse-novosti/688-knaazu-90-le','/index.php/news/vse-novosti/688-knaazu-90-let','/images/news/3G2A3408.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('690-s-dnem-rabotnikov-neftyanoj-i-gazovoj-promyshlennosti','С Днем работников нефтяной и газовой промышленности!','2020-01-01','novosti','[]','Поздравление председателя Хабаровской краевой организации профсоюза работников жизнеобеспечения Натальи Куц. Уважаемые работники и ветераны нефтяной и газовой промышленности! От имени Хабаровской краевой организации профсоюза работников жизнеобеспечения поздравляем вас с профессиональным праздником! Ни для кого не секрет, что газовая отрасль является одной из самых сложных и опасных отраслей эконо','/index.php/news/vse-novosti/690-s-dnem-rabotnikov-neftyanoj-i-gazovoj-promyshlennosti','/images/news/den-gazovika.png');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('693-priem-zayavok-na-premiyu-myagkaya-sila-prodlen','Прием заявок на Премию «Мягкая сила» продлен!','2020-01-01','novosti','[]','Подать заявки на участие можно до 1 декабря. Премия «Мягкая сила» учреждена Постоянной комиссией Генсовета ФНПР по защите социально-экономических прав трудящихся женщин. Соорганизаторами выступают АНО «Институт трудовых отношений и гражданского общества» и Центральная профсоюзная газета «Солидарность». Премия проводится в целях развития профсоюзных женсоветов (женских комиссий), эффективной защиты','/index.php/news/vse-novosti/693-priem-zayavok-na-premiyu-myagkaya-sila-prodlen',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('695-prozhitochnyj-minimum-dlya-trudosposobnogo-naseleniya-kraya-14-267-rublej','Прожиточный минимум для трудоспособного населения края - 14 267 рублей','2020-01-01','novosti','[]','Новый размер прожиточного минимума за 4 квартал 2015 года установлен в Хабаровском крае. Соответствующее постановление подписал губернатор Вячеслав Шпорт. Согласно документу, в среднем величина прожиточного минимума на душу населения теперь составляет 13 427 рублей. Для трудоспособного населения показатель достиг 14 267 рублей, для пенсионеров – 10 804 рублей, для детей – 13 940 рублей, - сообщает','/index.php/news/vse-novosti/695-prozhitochnyj-minimum-dlya-trudosposobnogo-naseleniya-kraya-14-267-rublej',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('698-v-kraevoj-profsoyuz-zhizneobespecheniya-voshli-novye-pervichki','В краевой профсоюз жизнеобеспечения вошли новые первички','2020-01-01','novosti','[]','Сразу тремя новыми первичными профсоюзными организациями пополнила свои ряды Комсомольская городская организация профсоюза работников жизнеобеспечения. Как пояснила председатель городского комитета Светлана Ноздратенко, за помощью к ней обратились работники котельных, находящихся на территориях войсковых частей Комсомольского района, которые рассказали о множестве неразрешенных проблем в области о','/index.php/news/vse-novosti/698-v-kraevoj-profsoyuz-zhizneobespecheniya-voshli-novye-pervichki',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('699-nikolaevsk-na-amure-nagrazhden-pochetnym-znakom-gubernatora-khabarovskogo-kraya-gorod-trudovoj-slavy','Николаевск-на-Амуре награжден почетным знаком губернатора Хабаровского края «Город трудовой славы»','2020-01-01','novosti','[]','Февраль 2016 года стал знаменательным для Николаевска-на-Амуре. Город награжден почетным знаком губернатора Хабаровского края «Город трудовой славы». - Эта награда – высшая степень признания вклада Николаевска-на-Амуре в Победу в Великой Отечественной войне, в восстановление разрушенного войной народного хозяйства, в развитие промышленного и оборонного потенциала России, а также его достижений в о','/index.php/news/vse-novosti/699-nikolaevsk-na-amure-nagrazhden-pochetnym-znakom-gubernatora-khabarovskogo-kraya-gorod-trudovoj-slavy',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('700-zavodu-vympel-40-let','Заводу «ВЫМПЕЛ» - 40 лет','2020-01-01','novosti','[]','Сегодня свой 40–летний юбилей отмечает Амурский патронный завод «ВЫМПЕЛ». Хабаровское краевое объединение организаций профсоюзов поздравляет коллектив предприятия с праздником. Хабаровское краевое объединение организаций профсоюзов поздравляет коллектив Федерального казенного предприятия «Амурский патронный завод «ВЫМПЕЛ» с 40-летием со дня образования. За четыре десятилетия в истории нашей страны','/index.php/news/vse-novosti/700-zavodu-vympel-40-let',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('703-kraevoj-profsoyuz-rabotnikov-zhizneobespecheniya-podvel-itogi-raboty-za-2015-god','Краевой профсоюз работников жизнеобеспечения подвел итоги работы за 2015 год','2020-01-01','novosti','[]','Выездное заседание президиума по подведение итогов года провела 26 февраля Хабаровская краевая организация профсоюза работников жизнеобеспечения. О том, чего удалось добиться в 2015 году, и какие задачи стоят перед краевым профсоюзом на 2016 год рассказывает его председатель Лилия Нестерова. - Несмотря на сложное экономическое положение в стране и, конечно, в регионе, предприятия нашей отрасли ста','/index.php/news/vse-novosti/703-kraevoj-profsoyuz-rabotnikov-zhizneobespecheniya-podvel-itogi-raboty-za-2015-god',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('704-v-sostav-kraevoj-organizatsii-profsoyuza-rabotnikov-gosuchrezhdenij-i-obshchestvennogo-obsluzhivaniya-kraya-voshla-n','В состав краевой организации профсоюза работников госучреждений и общественного обслуживания края вошла новая первичка','2020-01-01','novosti','[]','В состав краевой организации профсоюза работников госучреждений и общественного обслуживания края вошла профорганизация Управлении Федеральной миграционной службы России по Хабаровскому краю. Соответствующее решение 19 февраля принял президиум краевой организации профсоюза. Напомним, профорганизация была создана 25 января на организационном собрании в Управлении Федеральной миграционной службы Рос','/index.php/news/vse-novosti/704-v-sostav-kraevoj-organizatsii-profsoyuza-rabotnikov-gosuchrezhdenij-i-obshchestvennogo-obsluzhivaniya-kraya-voshla-novaya-pervichka',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('706-v-khabarovske-poyavitsya-gorodskaya-organizatsiya-profsoyuza-rabotnikov-narodnogo-obrazovaniya-i-nauki','В Хабаровске появится городская организация профсоюза работников народного образования и науки','2020-01-01','novosti','[]','18 февраля на площадке Хабаровского краевого профобъединения пройдет учредительная конференция городской организации профсоюза работников народного образования и науки г. Хабаровска. На конференцию избрано 77 делегатов. Среди приглашенных – начальник управления образования администрации г. Хабаровска Ольга Тен, а также более 100 руководителей образовательных организаций города. Как рассказали в кр','/index.php/news/vse-novosti/706-v-khabarovske-poyavitsya-gorodskaya-organizatsiya-profsoyuza-rabotnikov-narodnogo-obrazovaniya-i-nauki',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('707-profsoyuz-rabotnikov-obrazovaniya-dobilsya-uvelicheniya-minimalnykh-razmerov-stipendij','Профсоюз работников образования добился увеличения минимальных размеров стипендий','2020-01-01','novosti','[]','25 января Министерство образования и науки Российской Федерации направило в адрес ректоров российских вузов письмо, которое устанавливает увеличенные минимальные размеры стипендий с 1 января 2016 года. Такое решение профильного ведомства стало возможным благодаря встрече Министра образования и науки Российской Федерации Дмитрия Ливанова с Президиумом Студенческого координационного совета Общеросси','/index.php/news/vse-novosti/707-profsoyuz-rabotnikov-obrazovaniya-dobilsya-uvelicheniya-minimalnykh-razmerov-stipendij',NULL);
