INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('1030-tvorcheskij-festival-konkurs-sredi-trudovykh-kollektivov-vpervye-proshel-v-khabarovske','Творческий фестиваль-конкурс среди трудовых коллективов впервые прошел в Хабаровске','2020-01-01','novosti','[]','Фестиваль-конкурс "Хабаровский край - Мастерская талантов" завершился в минувшую субботу. На конкурс подано более 50 заявок из числа трудовых коллективов региона - г. Хабаровск; г. Комсомольск-на-Амуре; г. Амурск; г. Советская Гавань; п. Циммермановка, Ульчский муниципальный район; п. Николаевка, Смидовичский район, ЕАО; п. Чегдомын, Верхнебуреинский район; р.п. Хор, муниципальный район им. Лазо, ','/index.php/news/vse-novosti/72-aktsii-i-festivali/1030-tvorcheskij-festival-konkurs-sredi-trudovykh-kollektivov-vpervye-proshel-v-khabarovske',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('387-ispolkom-fnpr-utverdil-poryadok-provedeniya-aktsii-za-dostojnyj-trud','Исполком ФНПР утвердил порядок проведения акции «За достойный труд!»','2020-01-01','novosti','[]','30 августа на заседании Исполкома утвердили порядок проведения Всероссийской акции профсоюзов в рамках Всемирного дня действий «За достойный труд!». 7 октября во Всемирный день действий «За достойный труд!» профсоюзы проводят акции в защиту законных прав и интересов трудящихся. В этом году акция ФНПР и ее членских организаций пройдет под девизом «Социальное партнерство – гарантия достойного труда!','/index.php/news/vse-novosti/72-aktsii-i-festivali/387-ispolkom-fnpr-utverdil-poryadok-provedeniya-aktsii-za-dostojnyj-trud',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('696-luchshie-trudovye-dinastii-nagradili-v-khabarovske','Лучшие трудовые династии наградили в Хабаровске','2020-01-01','novosti','[]','Памятные знаки и подарки получили семь городских семей. Торжественная церемония чествования трудовых династий Хабаровска состоялась 18 марта в культурно-спортивном комплексе «Арсеналец». Награждение провела заместитель мэра Хабаровска по социальным вопросам Светлана Шевченко. Она вручила семи трудовым династиям дальневосточной столицы памятные знаки и подарки – денежные сертификаты на приобретение','/index.php/news/vse-novosti/72-aktsii-i-festivali/696-luchshie-trudovye-dinastii-nagradili-v-khabarovske',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('725-profsoyuz-rabotnikov-zhizneobespecheniya-kraya-opredelil-puti-razvitiya-profdvizheniya-v-otrasli','Профсоюз работников жизнеобеспечения края определил пути развития профдвижения в отрасли','2020-01-01','novosti','[]','Вопросы организационно-кадрового укрепления профсоюза обсудили на пленуме Хабаровской краевой организации профсоюза работников жизнеобеспечения. Как рассказала председатель краевой организации профсоюза Лилия Нестерова, в последние годы наблюдается стойкая тенденция к уменьшению числа работающих и членов профсоюза во всех отраслях, объединяемых краевой организацией. - Проводимое реформирование пре','/index.php/news/vse-novosti/725-profsoyuz-rabotnikov-zhizneobespecheniya-kraya-opredelil-puti-razvitiya-profdvizheniya-v-otrasli',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('727-vladimir-putin-otmetil-rabotu-profsoyuzov','Владимир Путин отметил работу профсоюзов','2020-01-01','novosti','[]','В преддверии 25-летия Федерации независимых профсоюзов России и 110-летия российского профсоюзного движения руководители профсоюзных организаций страны во главе с председателем ФНПР Михаилом Шмаковым встретились с Президентом России Владимиром Путиным. Встреча состоялась 27 октября в Кремле. Как сообщается на официальном сайте ФНПР , президент отметил необходимость совершенствования социальной под','/index.php/news/vse-novosti/727-vladimir-putin-otmetil-rabotu-profsoyuzov',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('739-komandirovochnye-udostovereniya-otmeneny','Командировочные удостоверения отменены','2020-01-01','novosti','[]','Ездить в служебные командировки станет намного проще. С этого года постановлением правительства РФ командировочные удостоверения в стране отменены. Отправляясь в служебную поездку по российским городам, и государственным служащим, и работникам бизнес-организаций больше не придется носить с собой командировочное удостоверение, на котором ставится печать о прибытии и отъезде. Теперь для определения ','/index.php/news/vse-novosti/739-komandirovochnye-udostovereniya-otmeneny',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('744-gazoviki-dalnevostochnogo-gazproma-otmetili-professionalnyj-prazdnik-semejnym-festivalem','Газовики Дальневосточного Газпрома отметили профессиональный праздник семейным фестивалем','2020-01-01','novosti','[]','День работников нефтяной и газовой промышленности сотрудники «Газпром газораспределение Дальний Восток» из Хабаровска, Петропавловска-Камчатского, Вяземского, Комсомольска-на-Амуре и Амурска отметили шестым по счету семейным фестивалем «ГазON» на туристической базе «Амур» в пригороде Хабаровска. --> --> --> --> --> Смотреть встроенную онлайн галерею в: https://habprof.ru/index.php/news/vse-novosti','/index.php/news/vse-novosti/744-gazoviki-dalnevostochnogo-gazproma-otmetili-professionalnyj-prazdnik-semejnym-festivalem','/images/news/1.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('748-prozhitochnyj-minimum-v-khabarovskom-krae-vyros','Прожиточный минимум в Хабаровском крае вырос','2020-01-01','novosti','[]','В Хабаровском крае установлена величина прожиточного минимума на второй квартал 2014 года. Соответствующее постановление, которое вступит в силу с 18 августа, подписал на днях губернатор Вячеслав Шпорт. Величина прожиточного минимума на одного человека определена для разных групп населения. Так, в среднем размер прожиточного минимума на душу населения в Хабаровском крае установлен на уровне 11 185','/index.php/news/vse-novosti/748-prozhitochnyj-minimum-v-khabarovskom-krae-vyros',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('754-prozhitochnyj-minimum-dlya-trudosposobnogo-naseleniya-v-krae-11-722-rublya','Прожиточный минимум для трудоспособного населения в крае - 11 722 рубля','2020-01-01','novosti','[]','Установлена новая величина прожиточного минимума в Хабаровском крае на третий квартал 2014 года. Соответствующее постановление подписал губернатор Вячеслав Шпорт. Величина прожиточного минимума на одного человека определена для разных групп населения. Так, в среднем размер прожиточного минимума на душу населения в Хабаровском крае установлен на уровне 11 056 рублей. Для трудоспособного населения -','/index.php/news/vse-novosti/754-prozhitochnyj-minimum-dlya-trudosposobnogo-naseleniya-v-krae-11-722-rublya',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('755-zakonoproekt-o-svobodakh-dlya-profsoyuzov-vnesen-v-gosdumu','Законопроект о свободах для профсоюзов внесен в Госдуму','2020-01-01','podderzhka','[]','В Государственную Думу РФ был внесен законопроект, который по словам авторов "расширяет возможности профсоюзов, а также возвращает им право на коллективные трудовые споры и забастовки". Автором документа стала группа депутатов «Справедливой России», - сообщает газета "Солидарность". Как говорится в пояснительной записке, ныне правом на переговоры обладают лишь профсоюзы, объединяющие в себе не мен','/index.php/news/vse-novosti/755-zakonoproekt-o-svobodakh-dlya-profsoyuzov-vnesen-v-gosdumu',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('756-reshat-voprosy-zanyatosti-effektivno-i-kardinalno-bez-profsoyuzov-nevozmozhno-vladimir-putin','Решать вопросы занятости эффективно и кардинально без профсоюзов невозможно - Владимир Путин','2020-01-01','novosti','[]','В рамках проходившего в австралийском Брисбене саммита глав государств и правительств стран Группы 20 Президент России Владимир Путин принял делегацию профсоюзной двадцатки L20, - сообщается на официальном сайте Федерации независимых профсоюзов России. - С некоторыми из вас мы встречались в прошлом году. Мне очень приятно, что эта традиция контактов между мировыми и профсоюзными лидерами продолжае','/index.php/news/vse-novosti/756-reshat-voprosy-zanyatosti-effektivno-i-kardinalno-bez-profsoyuzov-nevozmozhno-vladimir-putin',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('777-trudovye-pensii-vyrosli-na-6-5','Трудовые пенсии выросли на 6,5 %','2020-01-01','novosti','[]','С 1 февраля 2014 года трудовые пенсии в России увеличены на 6,5 %. Индексация произошла исходя из роста потребительских цен в 2013 году. Как сообщает пресс-служба Отделения Пенсионного фонда РФ по Хабаровскому краю , вырастет страховая часть трудовых пенсий по старости, пенсий по инвалидности и по случаю потери кормильца. При этом накопительная часть трудовой пенсии индексироваться не будет. Доста','/index.php/news/vse-novosti/777-trudovye-pensii-vyrosli-na-6-5',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('778-fnpr-perechislila-dopolnitelnuyu-pomoshch-postradavshim-ot-navodneniya-v-khabarovskom-krae','ФНПР перечислила дополнительную помощь пострадавшим от наводнения в Хабаровском крае','2020-01-01','novosti','[]','Более 1,2 миллиона рублей дополнительно на счет Хабаровского крайпрофобъединеия перечислила Федерация независимых профсоюзов России в помощь членам профсоюзов, пострадавшим от наводнения в Хабаровском крае. В ближайшее время средства будут выплачены адресатам. Напомним, в 2013 году специальная комиссия Хабаровского краевого объединения профсоюзов рассмотрела заявления и документы от пострадавших в','/index.php/news/vse-novosti/778-fnpr-perechislila-dopolnitelnuyu-pomoshch-postradavshim-ot-navodneniya-v-khabarovskom-krae',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('781-pochtovikam-povysyat-zarplatu','Почтовикам повысят зарплату','2020-01-01','novosti','[]','Почта России приступила ко второму этапу программы повышения заработной платы работникам предприятия. Согласно решению генерального директора ФГУП «Почта России» Дмитрия Страшнова выделены денежные средства на повышение окладов для всех сотрудников предприятия во всех регионах страны. Как сообщается на официальном сайте профсоюза работников связи России , повышение заработной платы почтовиков с ян','/index.php/news/vse-novosti/781-pochtovikam-povysyat-zarplatu',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('809-potrebitelskaya-korzina-v-khabarovskom-krae-po-novomu','Потребительская корзина в Хабаровском крае по-новому','2020-01-01','novosti','[]','На внеочередном заседании Законодательной Думы Хабаровского края в качестве закона был утвержден законопроект « О потребительской корзине и порядке установления величины прожиточного минимума в Хабаровском крае ». Как сообщает пресс-служба краевого парламфента, данный законопроект устанавливает порядок формирования потребительской корзины, ее состав, объем, а также порядок исчисления прожиточного ','/index.php/news/vse-novosti/809-potrebitelskaya-korzina-v-khabarovskom-krae-po-novomu',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('812-za-trudovye-zaslugi-v-krae-budut-prisvaivat-zvanie-veterana','За трудовые заслуги в крае будут присваивать звание ветерана','2020-01-01','novosti','[]','Краевая дума приняла закон « О присвоении звания «Ветеран труда Хабаровского края». Он призван по достоинству оценить заслуги граждан, внесших значительный вклад в развитие региона, но, в силу специфики федерального законодательства, не попадающих под условия присвоения звания «Ветеран труда». Согласно новому закону, ветеранами труда Хабаровского края могут стать граждане, имеющие трудовой стаж не','/index.php/news/vse-novosti/812-za-trudovye-zaslugi-v-krae-budut-prisvaivat-zvanie-veterana',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('823-opredeleny-novye-razmery-potrebitelskoj-korziny','Определены новые размеры потребительской корзины','2020-01-01','novosti','[]','Госдума России приняла в третьем чтении новый закон «О потребительской корзине в целом по Российской Федерации», разработанный Министерством труда и соцзащиты. Он вступит в силу с 1 января 2013 года, срок его действия составит пять лет. Согласно новому закону в потребительскую корзину будет включаться «необходимый для сохранения здоровья человека и обеспечения его жизнедеятельности минимальный наб','/index.php/news/vse-novosti/823-opredeleny-novye-razmery-potrebitelskoj-korziny',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('831-lyudi-v-maskakh-i-s-avtomatami-proveli-obysk-v-federatsii-profsoyuzov-kamchatki','Люди в масках и с автоматами провели обыск в Федерации профсоюзов Камчатки','2012-10-22','novosti','[]','Зайдя в свой кабинет 23 октября 2012 года, Председатель Федерации профсоюзов Камчатки, член Общественной палаты РФ Андрей Зимин застал взломанные кабинеты, развороченные сейфы, беспорядочно разбросанные бумаги и… початую бутылку коньяка. Это последствия проведенного накануне обыска людьми в масках. 22 октября 2012 года, воспользовавшись отсутствием Председателя Федерации профсоюзов Камчатки (далее','/index.php/news/vse-novosti/831-lyudi-v-maskakh-i-s-avtomatami-proveli-obysk-v-federatsii-profsoyuzov-kamchatki',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('834-chetvert-veka-plodotvornoj-raboty','Четверть века плодотворной работы','2020-01-01','novosti','[]','Четверть века исполнилось Координационному совету организаций профсоюзов в Комсомольске-на-Амуре. Торжественное собрание, посвященное юбилею, состоялось 28 сентября в Доме молодежи города юности. Координационный совет был создан в сентябре 1987 года и сегодня является представительством Хабаровского краевого объединения организаций профсоюзов в г. Комсомольске-на-Амуре. Он объединяет 214 первичных','/index.php/news/vse-novosti/834-chetvert-veka-plodotvornoj-raboty',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('869-v-khabarovskoj-kraevoj-organizatsii-profsoyuza-rabotnikov-zhizneobespecheniya-proshla-otchetno-vybornaya-kampaniya','В "первичках" регионального профсоюза работников жизнеобеспечения прошла отчетно-выборная кампания','2020-01-01','novosti','[]','До отчетно-выборной конференции крайкома осталось меньше двух месяцев. В первичных профсоюзных организациях прошли отчетно-выборные и отчетные собрания и конференции. 25 октября прошла XII отчетно-выборная конференция Комсомольской-на-Амуре городской организации профсоюза работников жизнеобеспечения. В ходе заседания председатель городского комитета Светлана Ноздратенко выступила с докладом об осн','/index.php/news/vse-novosti/869-v-khabarovskoj-kraevoj-organizatsii-profsoyuza-rabotnikov-zhizneobespecheniya-proshla-otchetno-vybornaya-kampaniya','/images/news/img_5640.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('870-v-fnpr-pomenyalas-struktura-upravleniya','В ФНПР поменялась структура управления','2020-01-01','podderzhka','[]','Руководящие функции в Федерации независимых профсоюзов России теперь распределены между президентом и председателем. Такое решение приняли делегаты XIII (внеочередного) Съезда профцентра, состоявшегося 29 октября в Москве. Съезд прошел в Колонном зале Дома Союзов. На него прибыли 327 делегатов, представляющих 122 членские организации ФНПР. Также в работе Съезда принял участие президент России Влад','/index.php/news/vse-novosti/870-v-fnpr-pomenyalas-struktura-upravleniya','/images/news/e2e5f7d9-6f62-4098-b879-b0b2a9db9435.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('871-blagotvoritelnyj-kontsert-v-podderzhku-khabarovskogo-kraevogo-muzykalnogo-teatra-proveli-profsoyuzy-regiona','Благотворительный концерт в поддержку Хабаровского краевого музыкального театра провели профсоюзы региона','2020-01-01','novosti','[]','В программу мероприятия вошли 17 номеров творческих коллективов и профессиональных артистов края. Площадкой для их выступлений стал Дворец культуры профсоюзов. --> --> --> --> --> --> --> --> --> --> --> --> Смотреть встроенную онлайн галерею в: https://habprof.ru/index.php/news/vse-novosti/871-blagotvoritelnyj-kontsert-v-podderzhku-khabarovskogo-kraevogo-muzykalnogo-teatra-proveli-profsoyuzy-regi','/index.php/news/vse-novosti/871-blagotvoritelnyj-kontsert-v-podderzhku-khabarovskogo-kraevogo-muzykalnogo-teatra-proveli-profsoyuzy-regiona','/images/news/IMG_8444.JPG');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('875-gensek-vseobshchej-konfederatsii-profsoyuzov-vstretilsya-s-profaktivom-khabarovskogo-kraya','Генсек Всеобщей конфедерации профсоюзов встретился с профактивом Хабаровского края','2020-01-01','novosti','[]','Генеральный секретарь ВКП Виктор Пинский рассказал коллегам о перспективах международного сотрудничества по вопросам защиты прав трудящихся, а также познакомился с местным опытом взаимодействия с профсоюзами Китая. Кроме того, Виктор Витальевич обозначил ключевые задачи и возможности Всеобщей конфедерации профсоюзов. Сегодня – это крупное международное профсоюзное объединение, под защитой которого','/index.php/news/vse-novosti/875-gensek-vseobshchej-konfederatsii-profsoyuzov-vstretilsya-s-profaktivom-khabarovskogo-kraya','/images/news/vstrecha-s-pinskim.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('888-pryamoj-efir-profsoyuznyj-podkhod-projdet-s-aleksandrom-shershukovym','Прямой эфир с Александром Шершуковым пройдет в конце рабочей недели','2020-01-01','novosti','[]','Уже в эту пятницу, 13 декабря, в 13:00 по московскому времени на канале «Солидарности» в Rutube состоится прямой эфир «Профсоюзный подход с Александром Шершуковым». Заместитель председателя ФНПР и главный редактор газеты «Солидарность» расскажет о самых значимых событиях уходящего года и что нас ожидает в новом 2025. Кроме того, у вас будет возможность задать эксперту свои собственные вопросы. Под','/index.php/news/vse-novosti/888-pryamoj-efir-profsoyuznyj-podkhod-projdet-s-aleksandrom-shershukovym',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('889-gubernator-vstretilsya-s-otraslevymi-profsoyuzami-regiona','Губернатор встретился с отраслевыми профсоюзами региона','2020-01-01','novosti','[]','Торжественный прием был приурочен ко Дню образования профсоюзного движения в Хабаровском крае. В минувшую среду наш регион отметил его впервые. Напомним, памятная дата была официально установлена в прошлом году постановлением Правительства края в целях популяризации профсоюзного движения, признания заслуг профсоюзов в защите трудовых прав работников, развития и повышения эффективности социального ','/index.php/news/vse-novosti/889-gubernator-vstretilsya-s-otraslevymi-profsoyuzami-regiona','/images/news/dfbhsfh.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('890-itogi-prazdnovaniya-dnya-obrazovaniya-profsoyuznogo-dvizheniya-v-khabarovskom-krae','Итоги празднования Дня образования профсоюзного движения в Хабаровском крае','2020-01-01','novosti','[]','В минувшую среду наш регион впервые отметил День образования профсоюзного движения. В рамках его празднования в течение прошлой недели в Хабаровском Профобъединении проходило множество мероприятий: - Открыла праздничную повестку тематическая онлайн викторина. В течение четырех дней читатели нашего телеграм-канала отвечали на 13 вопросов по истории профсоюзов края; - С понедельника по пятницу для в','/index.php/news/vse-novosti/890-itogi-prazdnovaniya-dnya-obrazovaniya-profsoyuznogo-dvizheniya-v-khabarovskom-krae',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('909-fnpr-provodit-vserossijskij-profsoyuznyj-konkurs-detskogo-risunka-2','ФНПР проводит Всероссийский профсоюзный конкурс детского рисунка','2020-01-01','novosti','[]','В объявленный ФНПР Год трудовой доблести «Всё для Победы!» Всероссийский профсоюзный конкурс детского рисунка приурочен к 80-летию Победы в Великой Отечественной войне. Приглашаем детей и внуков членов профсоюза Хабаровского края принять участие! Возраст — от 6 до 18 лет включительно. Тема конкурса: «Из одного металла льют медаль за бой, медаль за труд». Он пройдет в трех возрастных категориях: В ','/index.php/news/vse-novosti/909-fnpr-provodit-vserossijskij-profsoyuznyj-konkurs-detskogo-risunka-2',NULL);
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('910-postrojte-kareru-na-gossluzhbe-v-arktike-i-na-dalnem-vostoke','Постройте карьеру на госслужбе в Арктике и на Дальнем Востоке!','2020-01-01','novosti','[]','Успейте подать заявку на 4-й поток программы подготовки кадров для государственной службы и институтов развития Дальнего Востока и Арктики «Муравьев-Амурский 2030» до 17 марта 2025 года. Согласно поручению Президента России программа охватит Арктическую зону Российской Федерации, что вместе с Дальним Востоком создаст новые возможности для трудоустройства и участия в решении важных задач. Обучение ','/index.php/news/vse-novosti/910-postrojte-kareru-na-gossluzhbe-v-arktike-i-na-dalnem-vostoke','/images/news/3.png');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('911-zhitelej-khabarovskogo-kraya-priglashayut-podpisatsya-na-pabliki-80-let-velikoj-pobede-v-sotssetyakh','Жителей Хабаровского края приглашают подписаться на паблики «80 лет Великой Победе» в соцсетях','2020-01-01','novosti','[]','В преддверии 80-й годовщины Победы в Великой Отечественной войне 1941-1945 годов создан официальный сайт , а также открыты паблики в социальных сетях ВКонтакте , Одноклассники и телеграм-канал «80 лет Великой Победе». В сообществах собраны истории о том, как приближали Победу на фронте и в тылу, интересные факты о сражениях и героях, а также трогательные личные фронтовые письма и воспоминания. В Х','/index.php/news/vse-novosti/911-zhitelej-khabarovskogo-kraya-priglashayut-podpisatsya-na-pabliki-80-let-velikoj-pobede-v-sotssetyakh','/images/news/pobeda80_billboard_3_2_preview.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('918-fnpr-i-gazeta-solidarnost-zapuskayut-proekt-geroi-trudovoj-doblesti','ФНПР и газета "Солидарность" запускают проект "Герои трудовой доблести"','2020-01-01','novosti','[]','В ознаменование 80-летия Победы в Великой Отечественной войне 1941-1945 годов Исполком Федерации независимых профсоюзов России объявил 2025 год Годом трудовой доблести "Всё для Победы!". Более 16 млн человек были награждены медалью "За доблестный труд в Великой Отечественной войне 1941-1945 гг.". Среди них - профсоюзные работники и активисты. Центральная профсоюзная газета "Солидарность" и ФНПР за','/index.php/news/vse-novosti/918-fnpr-i-gazeta-solidarnost-zapuskayut-proekt-geroi-trudovoj-doblesti',NULL);
