INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('928-v-kraevom-profsoyuze-stroitelej-izbran-novyj-predsedatel','В краевом профсоюзе строителей избран новый председатель','2020-01-01','novosti','[]','Им стал Владимир Трофимов. Такое решение приняли делегаты 24 отчетно-выборной конференции организации. Пост заместителя заняла Наталья Смирнова. Работа крайкома за отчетный период была признана удовлетворительной. Кроме того, были избраны составы выборных органов, делегаты 31 отчётно-выборной Конференции Хабаровского Профобъединения и 8 Съезда Профсоюза строителей России. --> Версия для слабовидящ','/index.php/news/vse-novosti/928-v-kraevom-profsoyuze-stroitelej-izbran-novyj-predsedatel','/images/news/photo_2025-04-03_12-38-58.jpg');
INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('955-komissii-ispolkom-gensovet','КОМИССИИ, ИСПОЛКОМ, ГЕНСОВЕТ','2020-01-01','novosti','[]','21-22 апреля в Москве состоялись заседания коллегиальных органов ФНПР. 21 апреля проведены заседания постоянных комиссий Генерального Совета ФНПР и Молодёжного совета ФНПР. Члены постоянных комиссий Генерального Совета ФНПР рассмотрели проекты документов Генсовета, а также иные актуальные вопросы защиты прав трудящихся, социального страхования, нормотворческой деятельности, информационной работы, ','/index.php/news/vse-novosti/955-komissii-ispolkom-gensovet','/images/news/apb_3898.jpg');
