INSERT IGNORE INTO news (id,title,date,category,tags,excerpt,old_url,image) VALUES ('969-vserossijskij-seminar-soveshchanie-po-voprosam-orgraboty-proshel-v-sochi','Всероссийский семинар-совещание по вопросам оргработы прошел в Сочи','2020-01-01','novosti','[]','Он собрал более 100 участников из всех регионов страны, чтобы обсудить ключевые вызовы организационной работы в современных условиях. От Хабаровского Профобъединения участие в нем приняла заместитель председателя Наталья Мартыненко. В программе — обмен лучшими практиками проведения отчётно-выборных кампаний, мастер-классы по работе с единым реестром членов профсоюза и дискуссии о применении искусс','/index.php/news/vse-novosti/969-vserossijskij-seminar-soveshchanie-po-voprosam-orgraboty-proshel-v-sochi','/images/news/zal.jpg');
